(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-4"] = [{"a": [60], "v": 1, "p": 206, "ev": 1, "ep": 210, "sid": 207, "t": "قوله - عز وجل -:\n﴿وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَيۡنٗاۖ قَدۡ عَلِمَ كُلُّ أُنَاسٖ مَّشۡرَبَهُمۡۖ كُلُواْ وَٱشۡرَبُواْ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ﴾⟪2:60⟫\nالآية (60) - سورة البقرة.\nالاستسقاء طلب السقي أو الإسقاء، فالسقي أن يجعل له ماء يشربه، والإسقاء التعريض للماء، وجعله له ليتناوله منتى أراد، فهو أخص معنى من السقي، والسقي اسم مفعول نحو النقض والنكث، فيقال للماء سقي، وللأرض التي يجعل فيها الماء سقيا، والعصا اصله من الواو، بدلالة قولهم عصوته نحو هروته إذا ضربته بهما، وقيل عصيته بالسيف، وعصى فلان أصله أن يتناول العصا فيضرب بها، ثم كثر فعبر به عن الخارج من الطاعة، فصار العصا اسما للطاعة حتى قيل: شق فلان العصا، ولما كانت عادة المسافر ملازمة العصا قيل: ألقى فلان عصاه إذا ترك السفر ...\nوالانفجار والانبجاس، والانصداع والانشقاق يتقارب، لكن الانشقاق عام، والانصداع أكثر ما يقال في الأشياء الصلبة.\nوالانفجار في الأشياء اللينة، ومنه \" فجرة الوادي \" للمكان الذي ينبعث منه الماء، واستعير للخروج عن خطر الشريعة لتصور الفاجر بصورة الماء المنفجر من الحوض، واستعير الانفجار والانصداع والانشقاق لظهور الفجر، وقولهم: فجر أي كذب، هو استعمال لفظ عام في موضع خاص، فإن الكذب بعض الفجور، إذ قد يكون الفجور قولا وفعلا، والانبجاس يقارب الانفجار، إلا أن الانبجاس لا يكون إلا واسعا، والانفجار يستعمل في الضيق والواسع، فكل انبجاس: انفجار، وليس\n⟦1:207⟧\nكل انفجار انبجاسا، فإذا صح أن قيل ههنا: \" انفجرت \"، وفي غيرها: \" انبجست \" لأن العالم يستعمل أبدا مكان الخاص، والمشرب مكان الشرب، وسمي الشعر على الشفة العليا والعروق التي في باطن الخلق شارب لتصورهما بصورة الشاربين، واستعير الشرب والشبع لما يولج في المصبوغ، فقيل: ثوب مشرب ومشبع صبغا، و \" أشربت فلانا كذا \" مكنته في نفسه، وعلى ذلك ﴿وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ﴾⟪2:93⟫ والعبث والعثي يتقاربان نحو \" جذب \" و \" جبذ \"، يقال: عثى عثا، وعثى يعثوا عثوا، وعاث يعيث عيثا، إلا أن العيث أكثر ما يقال فيما يدرك حسا، والعثو فيما يدرك حكما،\nفإن قيل: فما فائدة قوله ﴿مُفۡسِدِينَ﴾⟪2:60⟫، والعثو ضرب من الإفساد، وقيل: قد قال بعض النحويين إن ذلك حال مؤكدة، وذكر ألفاظا مما يشبهه، وقال بعض المحققين، \" إن العثو وإن اقتضى الفساد فليس بموضوع له، بل هو كالاعتداء، وقد يوجد في الاعتداء ما ليس بفساد وهو مقابلة المعتدي بفعله، نحو: ﴿فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ﴾⟪2:194⟫، وهذا الاعتداء ليس بإفساد، بل هو بالإضافة إلى ما قوبل به عدل، فلولا كونه جزاء لكان إفسادا، فبين تعالى أن العثو المنهي عنه هو المقصود به الإفساد مكروه على الإطلاق، ولهذا قال: ﴿وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا﴾، وقد يكون في صورة العثو، والتعدي ما هو صلاح وعدل على ما تقدم، وهذا ظاهر، والمروي في الخبر أنه كان مع موسى - عليه السلام حجر إذا نزلوا منزلا وضعه فضربه بالعصاة فانفجرت منه اثنتا عشرة عينا لكل سبط عين، وأنكر ذلك بعض الطبيعيين واستبعده، وهذا المنكر مع أنه لم يتصور قدرة الله في\n⟦1:208⟧\nتغيير الطبائع والاستحالات الخارجة عن العادات، فقد ترك النظر على طريقتهم، إذ قد تقرر عندهم أن حجر المعناطيس يجر الحديد، وأن الحجر المنقر للخل ينفره، والحجر الطلاق يحلق الشعر، وذلك كله عندهم من أسرار الطبيعة، وإذا لم يكن مثل ذلك منكرا عندهم، ممتنع أن يخلق الله حجرا يسخره لجذب الماء من تحت الأرض، وقال بعض الناس: \" إن في الآية مع هذا المعنى الظاهر إشارة إلى معنى آخر دقيق، وهو أنه أريد بالعصا السياسة، وذلك يكثر في استعمالهم نحو قوله - عليه السلام: \" لا ترفع عصاك عن أهلك \" و \" شق فلان العصا \" إذا خرج عن السياسة المشروعة، وأريد بالحجر إسرائيل الذين وصفهم الله تعالى بقوله: ﴿ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ﴾⟪2:74⟫، وكان موسى - عليه السلام طلب لهم مداواة تعم جميعهم العالم والجاهل منهم \" وعموم المطر للبقاع العامرة والغامرة، فأمره الله تعالى أن يسوسهم سياسة ظاهرة بالعلوم والأعمال التي هي حمل الإسلام والإيمان وهو اثنتا عشرة خصلة التي بينها النبي - صلى الله عليه وسلم - في حديث جبرائيل [عليه السلام] ستة منها الإسلام، وهي: \" شهادة أن لا إله إلا الله وأن محمدا رسول الله، والصلاة والزكاة، والصيام والحج، وستة منها وهي: \" الإيمان بالله وملائكته وكتبه ورسله، واليوم الآخر، والقدر خيره وشره \"، وذلك أن هذه الأركان الاثنى عشر يتشارك في أصولها المكلفون وإن\n⟦1:209⟧\nاختلفت فروضهم في أحكامها وفروعها، وقيل أن \" استسقاء موسى - عليه السلام - لقومه هو طلب علوم لهم تعمهم وتقلهم من حيث لا يحتاج فيه أحد إلى الاستعانة بالآخر، بل يجري مجرى المطر \" العام للغني والفقير، فبين الله تعالى أن ذلك ليس من الحكمة، إذ قد جعل الدنيا على تفاوت بين بينها، ولذلك قال:\n﴿قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ﴾⟪43:32⟫، وأمره أن شرع لهم بالسنة الأسباط الأثنى عشر أنهارا من العلوم يتناول كل فرقة على قدر منزلته واستحقاقه من مشربه، وقيل: إن موسى - عليه السلام - طلب لهم العلوم الموهبية وهي الحكمة الحقيقية التي نبه عليها الخضر حيث قال له موسى عليه السلام: ﴿هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا﴾⟪18:66⟫، فبين الله تعالى له أن منزلة (بني إسرائيل) تقصر عن إدراك ذلك، وأمره أن يأخذهم بالعلوم والأعمال الظاهرة، وذلك هو الاعتقادات والعبادات والمعاملات والمزاجر التي قد بنيت عليها الشرائع كلها ولكل واحد من ذلك ثلاثة منازل منزلة الظالم والمقتصد والسابق، وهو العامة والجامة والخاصة، فالعامة تؤخذ منها بالقهر السلطاني، والجامة بالقهر العلمي والخاصة بالقهر اليقيني، فهذه اثنتا عشر خصلة من استكملها بلغ منزلة من وصفهم الله تعالى بقوله: ﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى﴾⟪47:17⟫ ووصف به أصحاب الكهف في قوله تعال: ﴿إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى ۝ وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ﴾⟪18:13-14⟫، الآية، وهذه الأقوال محققة في أنفسها وإن لم تكن مقصودة في الآية والله أعلم.\n⟦1:210⟧"}, {"a": [61], "v": 1, "p": 210, "ev": 1, "ep": 213, "sid": 211, "t": "قوله - عز وجل -:\n﴿وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرٗا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ﴾⟪2:61⟫ الآية: (61) - سورة البقرة.\nالصبر الحبس على المكروه، وذلك ضربان: أحدهما: حبس الغير، فيتعدى نحو: صبرت الدابة، وصبرت يمينه أي: حلفته بالله حلفة لا خروج لها منها، والثاني: حبس النفس، ولا يتعدى في اللفظ، وهو حبس النفس عما يقتضيه الهوى أو على ما يقتضيه \" الهوى \" والعقل، ويختلف مواقع الصبر، وربما خولف بين أسمائها بحسب اختلاف مواقعها فإن كان في مصيبة يقال له: صبر لا غير وضده الجزع وإن كان في محاربة سمي شجاعة، وضدها الجبن وإن كان في نائبة مضجرة، سمي \" رحب الصدر \" وضده \" ضيق الصدر \" والضجر والتبرم وإن كان في إمساك [النفس فضولات العكس، سمي قناعة وعفة وضدها الحرص والشره وإن كان في امساك] كلام في الضمير سمي كتمانا وضده الذل والإفشاء ثم الصبر ضربان: نفسي وبدني فالبدني: أكثر لأخساء الناس والنفسي: للأشراف ولذلك قال الشاعر:\nوالصبر بالأرواح يعرف فضله ...\nصبر الملوك، وليس بالأجساد\nوالطعام ما يغتذي به مأكولا كان أو مشروبا، وفي المشروب قالك ﴿وَمَن لَّمۡ يَطۡعَمۡهُ فَإِنَّهُۥ مِنِّيٓ﴾⟪2:249⟫ ورجل طاعم لمن يطعم، ويتجوز به لمن حسن حالة في المطعم، ويقال: قوس مطعمة ويعير مطعم ومطعمنا الباري لبرئته كل ذلك تصور أنها تطعم صاحبها، والواحد يقال على أوجه من حيث الجنس\n⟦1:211⟧\nفيقال: الإنسان والفرس واحد، أي من حيث الحيوانية، وواحد من حيث النوع، يقال زيد وعمرو واحد، أي من حيث الإنسانية واحد من حيث الشخص، وإن كان ذا أجزاء كثيرة، يقال: رجل واحد، وواحد من حيث الشرف، نحو قولهم: واحد دهره، وواحد من حيث العدد، وهو مبدأ العدد بمعنى أنه لو ارتفع ارتفعت الأعداد، [ولو ارتفعت الأعداد] لم يرتفع الواحد بها، فالواحد كيف ما أدرته وأجريته لم يزد فيه شيء ولم ينقص، فإنه يحفظ ذاته، ولذلك قيل: إن الواحدة في العدد أقرب الأشياء إلى معرفة وحدانية الله تعالى\nفإن قيل: كيف قال: ﴿لَن نَّصۡبِرَ عَلَىٰ طَعَامٖ وَٰحِدٖ﴾⟪2:61⟫، وكان لهم المن والسلوى؟ قيل: إن ذلك إشارة إلى مساواته في الأزمنة المختلفة، كقولك فلان يفعل فعلا واحدا في كل يوم وإن كثرت أفعاله إذا تحرى طريقة واحدة وداوم عليها، والدعاء أعم من النداء، فإن النداء يقال فيمن يكون بعيدا أو في حكم البعيد والدعاء فيه وفي القريب، وقوله: ﴿فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا﴾⟪2:61⟫ ذكر جواب الدعاء، ولم يذكر المطلوب في الأول لكونه معلوما كقولك: قل لفلان يعطني كذا، وتقديره: قل له أعطني يعطني، والنبت والنبات يقال لما ينبت الله ولمصدر نبت، وقد يقال ذلك لذوي الساق من الشجرة، وأنبت الغلام إذا راهق على طريق الاستعارة ولنبات عانته، والبقل مالا ينبت أصله ولا فرعه في الشتاء، وأبقل المكان: صار ذا بقل وتبقلت تناولته وبقل وجهه استعارة، والفوم: الزرع، وقيل: الحنطة خاصة، وقيل: الثوم، والثاء والفاء يبدل أحدهما من الأخرى نحوه جدث، وجدف، ومغافير، ومغاثير، وأدنى أي أوضع، ويعبر عن الوضيع بالدني، والخير يقال على ضربين: أحدهما الخير المطلق وهو الشيء النافع الحسن الملذ وضده الشر المطلق وهو الضار القبيح المؤلم، والثاني: الخير المفيد، وهو ما يحصل فيه أحد الأوصاف الثلاثة، فيصح أن يوصف بالخير مرة والشر مرة على نظرين مختلفين، نحو أن يقال المال خير والمال شر، ولأجل أن الخير المطلق هو ما جمع الأوصاف الثلاثة،\n⟦1:212⟧\nوهي غاية ما يتحرى ويطلب، قيل الخير: هو الذي يطلبه الكل، والشر هو الذي يهرب منه الكل، فإن ما جمع الحسن واللذة والنفع يرغب فيه الكل، وما جمع منه أضداده الثلاثة يهرب منه الكل، والمصر: اسم لكل بلد عظيم مجموع الأقطار والحدود، وهو في الأصل اسم للمصور أي المضموم بالحدود نحو النقص والنكث للمنقوص والمنكوث، وعبر عن الحد بالمصر في قول الشاعر:\nوجاعل الشمس مصرا لاخفاء به\n....\nبين النهار وبين الليل قد فصلا\nمن حيث إن الحد معتبر فيه، ومصرت الناقة جمعت ضرعها بإصبعين للحلب، ولما كان خروج اللبن على ذلك قيل غير مصور لقليلة اللبن، و \" فلان مصور \" أي بخيل يعسر إخراج الشيء منه تشبيها بذلك، فمصر ههنا قيل هو البلد المعروف، ولذلك قيل هو في قراءة أبي - رضي الله تعالى عنه - بغير تنوين، وقيل: عنى به مصرا من الأمصار، والذلة تقال على وجهين، على الهون وقريء: ﴿وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ﴾⟪17:24⟫ والمسكنة: الفقر الذي يسكن الإنسان عن التصرف، ومعنى ﴿وَضُرِبَتۡ عَلَيۡهِمُ﴾⟪2:61⟫ أي ألزمت وأوجبت - تشبيها بضرب الخيمة على من فيها والإحاطة به، و \" باؤا \" أي احتملوا، وأصل ذلك من البوأ أي المساوية، فباء فلان بكذا تنبيه أنه تحمل مقدار ما يساوي وقوته، والمباءة: المنزل في المستوى، وذلك إذا لم يكن ذا عد، وبين الله تعالى في هذه الآية أنه لما اختار الله لهم ما يتبلغون به، أبوا إلا الميل إلي القاذورات وما فيه مراعاة القوة\n⟦1:213⟧\nالبهيمية، والعناية بتربيتها فقال: ﴿أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ﴾⟪2:61⟫ أي أخس بما هو خير مطلق، ثم قال: ﴿ٱهۡبِطُواْ مِصۡرٗا﴾⟪2:61⟫ وذلك على نحو: ﴿ٱعۡمَلُواْ مَا شِئۡتُمۡ﴾⟪41:40⟫ فكأنه قيل: إن لم ترغبوا فيما اخترته لكم، وفيه خلاصكم، فشأنكم في قصد المكان الذي لا يعدم فيه ما ترمونه، وذكر ثلاثة أحوال كل واحدة كالمعلول للأخرى، فقال: ﴿ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ﴾⟪2:61⟫ أي حصلت لهم هذه العقوبة التي هي الذلة والمسكنة والغضب من أجل كفرهم بآيات الله وقتلهم النبيين، وحصل لهم الكفر، وقتل النبيين بالعصيان والاعتداء، وذلك أنه كما أن الخيرات صغارها سبب لتحري كبارها، كذلك الشرور صغارها سبب لارتكاب كبارها، فبين أنهم لما عصوا وتعدوا، أدى ذلك بهم إلى الكفر وقتل الأنبياء، وأدى ذلك بهم إلى أن ألزموا الذلة والمسكنة، وغضب الله عليهم، وفيها تنبيه لنا أن من طلب لنفسه غيره ما أثره الله له، فقد خرج من التوكل بل قد تعدى فقد قيل: (ومن لم يهتد بما يختاره الله له، لم يهتد بما يختاره لنفسه)، ولهذا قيل في الدعاء: \" اللهم لا تكلني إلى نفسي طرفة عين، وأكلني كلاية الوليد في المهد \"."}, {"a": [62], "v": 1, "p": 213, "ev": 1, "ep": 216, "sid": 214, "t": "قوله- عز وجل:\n﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَعَمِلَ صَٰلِحٗا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪2:62⟫ الآية: (62) - سورة البقرة\nالهود: قبل التوبة، لقوله تعالى: ﴿إِنَّا هُدۡنَآ إِلَيۡكَۚ﴾⟪7:156⟫ أي تبنا، ومنه أخذ اليهود وقيل: أصل اليهود ويهدوا منقول عن السريانية، وهو أقرب وهاد فلان إذا تحرى طريقتهم في الدين، والاسم العلم قد يتصور منه [معنى] ما يتعاطاه المسمى به والمنسوب إليه ثم يشتق منه، نحو قولهم تفرعن فلان، إذا تحرى في فعله الجور الذي كان يتعاطاه فرعون، و \" تطفل فلان \" إذا فعل فعلا\n⟦1:214⟧\nطفيل في كونه وارثا أو فاعلا في الدعوات، وقالوا: \" لاط فلان وتلوط \" إذا فعل فعل آل (قوم) لوط، وهذا أبعد من الأول، ولما كان دين اليهود قبل أن ينسخ دين حق قيل لمن تاب \" هاد \" حتى كثر ذلك، ولما تصور منه الحركة عند القراءة شبه بهم المتحرك طورا والماشي مشيا مخصوصا طورا، فقيل: تهود فلان في مشية \" و \" هود الرابض الدابة \" إذا سيرها برفق وأما النصارى، فقد قيل: هو مما حكي عن المسيح ﴿مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ﴾ والأقرب ما قال بعضهم إن المسيح كان من قربة يقال لها نصران، فإما أن سموا باسمها، ثم جمعته العرب على نصارى نحو: \" سكران \" و \" سكآرى \" أو جعلوا منسوبين إليها ثم جمعت نحو: \" مهرى \" و \" مهارى \" و \" الصائبون \"، قيل: قوم كانوا على دين نوح، وذلك كان من أديان الحق قبل النسخ، وقولهم: \" صبأ فلان \" إذا اخرج من دينه إلى دين آخر يجوز أن يكون أصله فيمن كان يخرج إلى دينهم ثم صار يستعمل في كل دين كقولهم ألها لكي في أن أصله لحداد مخصوص، ثم صار يستعمل في كل حداد، ويكون أن يكون \" صباعربيا \" طابق ذلك، و \" صباناب البعير \" طلع، ومن قرأ: \" صابئين \" فقد قيل هو من: صبا يصبو، وقيل: أصله \" صبا \"، فترك همزه، والأجر والجزاء والثواب يتقارب، لكن الأكثر في الجزاء أن يستعمل في المعاملة بين الأكفاء أو فيما يجري مجراه بضرب من التلطف والأجر فيما يعطى الرفيع من دونه والثواب فيما يرجع إلى الإنسان من نفع عن فعله، وقد تقدم أن الإيمان يستعمل على وجهين: أحدهما: الإقرار بالشهادتين الذي يؤمن نفس \" الإنسان \" وماله عن الإباحة إلا بحق، وذلك بعد استقرار هذا الدين مختص به، كالإسلام، والثاني: تحري اليقين فيما يتعاطاه الإنسان من أمر دينه فقوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ﴾⟪2:62⟫ عنى به المتدين بدين محمد - صلى الله عليه وسلم - وقوله: ﴿مَنۡ ءَامَنَ بِٱللَّهِ﴾⟪2:62⟫ عنى به المتحري\n⟦1:215⟧\nللاعتقاد اليقيني، فهو غير الأول ولما كانت مشاهير الأديان هذه الأربع، بين الله تعالى أن كل من تعاطى دينا من هذه الأديان في وقت شرعه، وقبل أن ينسخ عنه، فتحرى في ذلك الاعتقاد اليقيني، واتبع اعتقاده بالأعمال الصالحة، فلا خوف عليهم ولا هم يحزنون، وبين صحة ذلك ما روي أن سلمان الفارسي - رضي الله عنه - لما ذكر له خبر النبي - صلى الله عليه وسلم - قصده وآمن به، وذكر حسن أحوال رهبان صحبهم، قال النبي - عليه السلام: \" ما تواوهم في النار \"، فأنزل الله تعالى هذه الآية، ثم قال عليه السلام: \" من مات على دين عيسى قبل أن يسمع بي، فهو على خير ومن سمع بي ولم يؤمن بي فقد هلك \" وقول ابن عباس رضي الله تعالى عنهما وسعيد - رضي الله عنه - \" إن هذا منسوخ بقوله: ﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ﴾⟪3:85⟫ يعنون أن هذه الأديان كلها منسوخة بدين الإسلام، وأن الله - عز وجل جعل لهم الأجر قبل وقت النبي - عليه السلام -، فأما في وقته، فالأديان كلها منسوخة بدينه\n....\n⟦1:216⟧"}, {"a": [63], "v": 1, "p": 216, "ev": 1, "ep": 217, "sid": 217, "t": "قوله - عز وجل:\n﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:63⟫\nالآمة: (63) - سورة البقرة \".\nالميثاق: عقد مؤكد بمين أو عهد، يقال: أوثقت كذا ووثقته ووثق به ثقة، ثم قيل: رجل ثقة، وقوم ثقة، فاستعير لفظها للموثوق به، والميثاق الذي أخذ منهم ما ذكره الله تعالى في قوله: ﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ﴾⟪2:83⟫، وفي قوله: ﴿وَلَقَدۡ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَيۡ عَشَرَ نَقِيبٗاۖ﴾⟪5:12⟫ وفي قوله: ﴿وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ﴾⟪3:81⟫ الآية، والطور: قيل هو اسم لجبل مخصوص وقيل: هو اسم لكل جبل ينبت شيئا، وطابق لفظه الطور أي الفناء و \" طار يطور \" لسرعة المشي، كما أن طار يطير للسباحة في الهواء، والقوة يستعمل تارة بمعنى القدرة، وتارة للتهيؤ الموجود في الشيء، نحو أن يقال: النوى بالقوة \" نخلة \"، أي متهيأ ومترشحآ أن يكون منه ذلك، ويستعمل القوة في البدن تارة، وهو الأظهر، وتارة في النفس، ولما كانت القوة للشدة الموجودة في الشيء سميت المفازة قوى - تصورا منها ذلك، ثم قيل: أقوى فلان، إذا صار في قوى، أي قفر، وتصور من حال الفقر الفقر، فاستعير الأقوى للافتقار استعارة قولهم أترب وأرمل، لذلك، فقوله: ﴿خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةٖ﴾⟪2:63⟫ أي: تعاطوا ما فيه بعلم ودراية فالعلم هو الذي يقوي الإنسان ويبلغه المقصود في أمور الدين، وقال الضحاك: (بقوة): أي بطاعة الله، وذلك لما روى \" أقوى الناس من أطاع الله واتقاه \"، وقيل: \" بقوة، أي بعمل ما فيه، وذلك صحيح بنظر فإن تعاطي كل جزء من العمل الصالح يقوي الإنسان على ما فوقه، وقد تقدم أن الذكر ذكران ذكر باللسان، وذكر بالقلب وأنه يتجوز به في الحفظ والمراعاة، فيقال: اذكر كذا، كما يقال في الترك: النسيان، وذاك أن الذكر سبب\n⟦1:217⟧\nلحفظ صورة الشيء في النفس، كما أن النسيان والترك سبب لانحداقها عنها، فمن قال: الذكر والنسيان ليسا من فعل الإنسان، فإنما نظر إلى الغاية التي هي السبب دون المبدأ الذي هو السبب ومن قال \" قد يكون من فعل الإنسان، فإنما اعتبر السبب الذي عنده يحصل ويثبت صورة الشيء في النفس، وعنده ينحذف، ومعنى الآية: قلت إن موسى - عليه السلام - لما أتى بني إسرائيل بالتوراة متضمنة لأحكام شريعتهم، أبوا أن يلزموها، فأمر الله الملائكة أن ترفع الطور، فقيل لهم: خذوها وإلا طرح عليكم، وذلك قوله: ﴿وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةٞ وَظَنُّوٓاْ أَنَّهُۥ وَاقِعُۢ بِهِمۡ﴾⟪7:171⟫ الآية\nإن قيل: إن هذا يكون إلجاء، ولا يستحق به الثواب، قيل: لم يستحقوا الثواب بالالتزام، وإنما استحقوا بالعمل بها من بعد، فأما في التزامها فمضطرون، وقال بعض الناس: \" عني برفع الطور تشديد الأمر عليهم وجعل ذلك مثلا \"، وذلك بعيد، وقوله: ﴿وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ﴾⟪2:63⟫، الواو فيه للحال لا للعطف، لأن أخذ الوثاق كان بعد رفع الطور، وذلك نحو قول الشاعر:\nقالت ولم تقصد لقيل الخنا\n....\nمهلا فقد أبلغت إسماعي"}, {"a": [64], "v": 1, "p": 217, "ev": 1, "ep": 219, "sid": 218, "t": "قوله- عز وجل:\n﴿ثُمَّ تَوَلَّيۡتُم مِّنۢ بَعۡدِ ذَٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَٰسِرِينَ﴾⟪2:64⟫\nالآية: (64) سورة البقرة.\nالتولي: التفعل من الولاية في الأصل، ويقتضي تولى الأمر حصوله في أقرب المواضع منه، وإذا قيل: تولى عنه، فمعناه ترك التولي معرضا، فالتولي عن الشيء أخص من الإعراض، والافضال والإحسان والإنعام لا يكاد يفرق بينهما في التعارف سيما إذا وصف به الباري سبحانه وإن كان قد\n⟦1:218⟧\nيخلف في أصل الموضوع، ومن حيث الاشتقاق فالإفضال بذل مالا يجب عليه، أو ترك ما يجب له وذلك من الفضل وهو الزائد على العدل، والإحسان.\nالفعل الحسن سواء كان واجبا وعدلا أو نافلة وزائدا على العدل وأن كان في قوله تعالى: ﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ﴾⟪16:90⟫ الآية ما يقتضي ما يزيد على العدل والإنعام يقتضي ما يتنعم به المنعم عليه، ولا يكاد يقال في التعارف يقال فيما يقتنيه الإنسان في نفسه هذه، وفيما يعطي غيره تارة، فيقال فيهما: فلان ذو فضل، والثاني هو المراد ههنا، وقول أبي العالية والربيع: \" إن فضل الله الإسلام \"، ورحمته \" القرآن \"، فذلك بعض ما يقتضيه عموم اللفظ، ولكن في قولهما تنميه، إن هذا خطاب لمن كان في زمان النبي - صلى الله عليه وسلم - دون المتقدمين، والخاسر المطلق في القرآن هو الذي خسر أعظم ما يقتني، وذلك [نعيم] الأبد، وهو المذكور في قوله: ﴿قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ﴾⟪39:15⟫، إن قيد: إن ذلك يقتضي أن لا فضل له تعالى على الذين خسروا [أنفسهم]، قيل: تخصيص من انتفع بذلك من حيث إنه قبله لا يقتضي إن لم يعرض فضله لغيره فإن فضله تعالى الديني معرض لكل أحد، لكن حق الإنسان أن يترشح بقبوله والانتفاع به، فمثله كمثل نعمته بالشمس والصوب اللذين وإن كانا عامين لا ينتفع بهما من زرعه من لم يرشحها للانتفاع بهما، كذلك فضله الديني والعقلي لا ينتفع به من لم يرشح نفسه بقبوله ..\n⟦1:219⟧"}, {"a": [65], "v": 1, "p": 219, "ev": 1, "ep": 221, "sid": 220, "t": "قوله عز وجل:\n﴿وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ﴾⟪2:65⟫\nالآية: (65) سورة البقرة\nالعلم ههنا بمعنى المعرفة ويتعدى ذلك إلي مفعول واحدة وحقيقة ذلك أن معارفنا ضربان.\nأحدهما: حصول صور الموجودات في النفس وذلك كالمعرفة بذات الشيء، والثاني: الحكم بوجود شيء لشيء هو موجد له، أو الحكم بنفي شيء عن شيء هو منتف عنه، فالأول: يقال له معرفة وعلم، ويتعدى إلى مفعول واحد، وعلى ذلك قوله: ﴿وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِينَ ٱعۡتَدَوۡاْ مِنكُمۡ فِي ٱلسَّبۡتِ﴾⟪2:65⟫، وقوله: ﴿لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ﴾⟪8:60⟫ والثاني: يقال له علم، ولا يقال له معرفة، ويتعدى إلى مفعولين لا يصح الاقتصار فيه على أحدهما من حيث إن ذلك يقتضي إثبات حكم أو نفي حكم لمعلوم، والاعتداء مجاوزة الحق على وجه محظور قال الحسن: كان اعتداؤهم في السبت أخذهم الحيتان على جهة الاستحلال وقيل: حبسهم إياها في الشباك يوم السبت ليأخذوها يوم الأحد، والسبت في الأصل راحة بعد تعب، واستعمل في الشعر إذا حلق لهذا المعنى، وفي الجلد إذا أزيل عنه الشعر تشبيها به، وقيل للنعل \" سبت \"، أي مسبوت نحو نقض، ونكث، والسبات للنوم من ذلك، والسبت قيل جعل اسما للنوم من ذلك، وخسأت الكلب فخسأ، زجرته فانزجر وخسأ البصر من ذلك أي انقبض، وقوله ﴿فَقُلۡنَا لَهُمۡ كُونُواْ قِرَدَةً خَٰسِـِٔينَ﴾⟪2:65⟫ أي جعلناهم، فذكر القول ههنا تنبيها على سرعة جعله كذلك نحو قوله: ﴿إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ﴾⟪16:40⟫، أي جعلنا له وبيان جعله الإنسان قردة وخنازير يحتاج فيه إلى مقدمة وهي أن الإنسان أتم ما أوجده الله تعالى في هذا العالم وأشرف ، فإن الأعيان المبصرات بالقول المجمل أربعة، الجماد [وهو الجسم غير النامي]، ثم النبات وهو الجسم النامي، ثم الحيوان، وهو النامي\n⟦1:220⟧\nالحساس، ثم الإنسان وهو الحساس المروي، فللإنسان صورتان، مهما باين ما سواه إحداهما مدركة بالحاسة، وهو الشكل المخصوص، والثانية مدركة بالعقل، وهو ما خص به من قوة الفكر والتمييز والعقل، فالإنسان بهذه القوة يشابه الملائكة وبقوته الشهوية والعضبية يشابه البهائم، فصار واسطة بين القبيلين، وفيه تكمن من التشبيه بالقلبيلين، أما تشبيهه بالملائكة، فبإماتامة قوته الشهوية بقدر الطاقة وتربية قوته الفكرية وتعاطيه ما وصف الله به الملائكة في قوله: ﴿لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ﴾⟪66:6⟫، وأما تبيهه بالبهائم، فبإماماتق قوته الفكرية وتربية قوته الغضبية والشهوية وتعاطيه ما وصف الله به الكفار، فقال: ﴿يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ﴾⟪47:12⟫ وقال: ﴿أُوْلَٰٓئِكَ كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّۚ﴾⟪7:179⟫، فإذا ثبت ذلك، فمن اعتبر الصورة المعقولة قال: هذا مثل ضربه الله لهم كقوله: ﴿كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ﴾⟪62:5⟫، وقوى ذلك بقوله: ﴿وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَۚ﴾⟪5:60⟫ وإليه ذهب مجاهد ومن اعتبر الصورة الشكلية قال: جعلهم على شكل القردة والخنازير كذا روى عن ابن عباس - - رضي الله تعالى عنهما - والحكمة تقتضي الأمرين إدا تحرى بذلك ردع الكافة، فإن تغيير الصور المعقوبلة لا يعرفه إلا الخاصة هن أولي البصائر والعقول الراجحة وتغيير الصور الحساسة يشاركهم فيها العامة وأصحاب الحواس والدين لايرتدعون إلا بما تدركه حواسهم فتبهرهم وغيرهم.\n⟦1:221⟧"}, {"a": [66], "v": 1, "p": 221, "ev": 1, "ep": 222, "sid": 222, "t": "قوله - عز وجل:\n﴿فَجَعَلۡنَٰهَا نَكَٰلٗا لِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةٗ لِّلۡمُتَّقِينَ﴾⟪2:66⟫ الآية: (61) سورة البقرة.\nالنكال: العقوبة الرادعة على سبيل القهر والفضيحة المشهورة، وهو منقول عن نكل فلان عن كذا أي ارتدع، ومنه النكل للقيد ولحديدة اللجام ولكل ما ينكل به، والوعظ ردع بالعبارة والإحالة على الاعتبار، وقوله: ﴿لِّمَا بَيۡنَ يَدَيۡهَا﴾⟪2:66⟫ أي لما في زمانها، (وما خلفها) أي لن بعدها، ولما كانت عامة السياسات ضربين، قهرية وهي للعامة وذلك بالنكال ووعظية، وهي للخاصة وذلك بالقال ذكر الله تعالى أنه جمع في دلك الأمرين نكالا لعامتهم وموعظة لخاصتهم وهم المتقون، فإن قيلت لم قال ﴿لِّمَا بَيۡنَ يَدَيۡهَا﴾⟪2:66⟫ ولم يقل لمن بين يديها؟ قيل في ذلك تنبيه على لطيفة وهي أن لفظة (ما) يعبر بها عن الأجناس من الحيوان وغيره ومن لا يعبر به مفردا إلا عن العقلاء، ولما قال في الجهلة ﴿إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ﴾⟪25:44⟫ استعير لهم لفظ ما تنبيها على ما ذكرنا، وعلى دلك كثير مما وضع ما وضع من في كلامهم، وبكشف ذلك قوله تعالى: ﴿إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ﴾⟪8:55⟫، فجعلهم شر الدواب كما\nجعلهم في الأولى أضل من الأنعام، وبهذا المعنى ألم بعض المحدثين في قوله:\nحولي بكل مكان منهم خلق\n....\nتخطي إذا جئت في استفهامهم بمن\nوقال بعض الأدباء قوله: ﴿وَمَا خَلۡفَهَا﴾⟪2:66⟫ نصب وملفوف على الهاء في قوله: فجعلناها أي جعلنا هذه العقوبة وهو المسح وما خلفها من عذاب النار عقوبة ﴿لِّمَا بَيۡنَ يَدَيۡهَا﴾⟪2:66⟫ أي لذنوبهم المتقدمة [والله أعلم].\n⟦1:222⟧"}, {"a": [67], "v": 1, "p": 222, "ev": 1, "ep": 224, "sid": 223, "t": "قوله - عز وجل:\n﴿وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تَذۡبَحُواْ بَقَرَةٗۖ قَالُوٓاْ أَتَتَّخِذُنَا هُزُوٗاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾⟪2:67⟫ الآية: (67) سورة البقرة.\nقد فرق العرب بين كثير من ذكور مشاهير الحيوان وإناثها في الأسماء فقالوا: رجل وامرأة وجمل وناقة وثور وبقره وعير وأتان، وجعلوا في عامة ذلك اسما يجمعها كالإنسان والبعير والحمار وربما جمعوها تحت أحد اسمي الذكر والأنثى كقولهم البقر والضبع وقيل: سمي البقر لأنه يبقر الأرض، أي يشقها، والأقرب أن يكون البقر أصلا في الباب، ثم اشتق منه هذه الأفعال بحسب تصورها منه، فلما عرف من البقر هذا الفعل اشتق من لفظه بقر، وشبه به بقر فلان بطن فلان، وتصور انفعال من البقر ما فيه من البلادة، فاشتق منه بقر فلان إذا تبلد في الأمر تبلد البقر وتصور منه أسرار مضطرب، فقيل بقر إذا أسرع إسراعه، وقيل لجماعة البقر بقرنحو الحمير والكلاب، وقيل الباقر للبقر وأصحابها وعلى ذلك الخامل، وذلك كقولهم لابن وتامر في أنه اسم للبن وصاحبه لكن الباقر يستعمل لجماعة البقر منفردا، نحو قول الشاعر :\nوما ذنبه أن عافت الماء باقره\nوالعوذ: الالتجاء إلى الغير والتعلق به، وعوذه إذا أرقاه منه، والعوذة اسم لما يعاذبه من الشر، وقيل: أطيب اللحم عوذه أي ما عاذ بالعظم وتمسك به، والجهل عدم العلم، وربما جعله أهل اللغة وبعض المتكلمين معنى مقتضيا للأفعال الخارجة على النظام، وعلى ذلك قالت العرب المجهلة للأمر\n⟦1:223⟧\nأو للأرض أو الخصلة التي تحمل الإنسان على الاعتقاد في الشيء على خلاف ما هو به، أو على إيقاع الفعل على غير ما يجب، وقالوا: استجهلت الريح الغصن إذا حركته حركة شديدة، ويجب أن يعلم أن الجهل ضربان: أحدهما افتقاد العلم، والثاني تصور الشيء بخلاف ما هو عليه، وهو أعظم الجهلين، ولما لم يسم كثير من المتكلمين الضرب الأول جهلا حدوا الجهل بأنه اعتقاد الشيء على خلاف ما هو به، لكن لا كان افتقاد العقل يقال له جهل حتى يقال عاقل وجاهل، كما يقال عالم وجاهل صار عدم العلم مسمى بالجهل، والهزؤ مرح مع عيب وأما السخرية، فمعه تسخير بالفعل، ولهذا قال تعالى: ﴿لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ﴾⟪43:32⟫ وهو أن يجعله منقادا لك بضرب من الهزو، ولما قال موسى لهم: اذبحوا بقرة، واستطرقوا هذا الحديث، فقالوا لغباوتهم وقلة تثبتهم: ﴿أَتَتَّخِذُنَا هُزُوٗاۖ﴾⟪2:67⟫، فأجابهم بجواب مختصر متضمن لمقدمتين ونتيجة، فقال، ﴿قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾⟪2:67⟫ فكأنه قال: الهازئ جاهل، والجهل منتف عنى فإذا لست بهازئ، وأخرج ذلك بقوله: أعوذ بالله مخرج منكر منقطع لما رمى به، فإن قيل كيف جعل الهازئ جاهلا وقد يهزأ الإنسان وليس بجاهل؟ قيل: لما كان يقال لمن اعتقد قي الشيء خلاف ما هو به جاهل، ولمن فعل مالا يقتضيه العلم وإن لم يعتقد فيه خلاف ما هو به جاهل، والهازئ إما أن يهزأ، لاعتقاده أن ذلك يجوز أو لا يعتقد ذلك، ولكن يفعل مالا يقتضيه العلم، فيصح من هذا الوجه أن يقال هو جاهل، فإذا كل هازئ جاهل على أحد هذيان الوجهين.\n⟦1:224⟧"}, {"a": [68], "v": 1, "p": 224, "ev": 1, "ep": 225, "sid": 225, "t": "قوله - عز وجل:\n﴿قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا فَارِضٞ وَلَا بِكۡرٌ عَوَانُۢ بَيۡنَ ذَٰلِكَۖ فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ﴾⟪2:68⟫ الآية (68) من سورة البقرة.\nالتبيين كالتعريف، إلا أن التبيين يقتضي إظهار الفضل بين الشيء وغيره، والتعريف قد يكون إظهار الشيء في نفسه من دون اعتبار بغيره واشتقاق ذلك من البين وهو المسافة بين الشيئين، وأصل الفرض قطع الحديد وهو أبلغ من الفرض، والمفراض والمقراض ما يقطع به الحديد، ونحوه وفرض الزند والقوس مستعار من ذلك وكذا فرضه الماء [للمقسم المحكوم به] وقيل لما أوجب وقطاع به الحكم فرض كفرض العبادة وما ألزم إعطاؤه من المال، وسمي ما يؤخذ في الصدقة من [الإبل والبقر والغنم] فريضته، والفارض من البقر يجوز أن يكون من هذا، لأن السائغ في الصدقة من سن البقر اثنان، التبيع والمسنة فالتبيع يجوز في حال دون حال والمسنة يصح بدلها في كل حال، فيجوز أن يكون سمى فارضا لهذا، وقيل فرضت البقر، وفرضت والبكر المتقدم على أمثاله في السن وبه سمي البكر، وأول نكاح وأول مولود وأول والد ووالدة، وقيل في البعير بكر، وفي الفواكه باكورة وبكل فلان في الحاجة إذا تعجل، وعلى ذلك قوله:\nبكرت تلومك بعد وهن في الندى\nوالعوان: الوسط بين السنين وهو المحمود لأنه بين الحالين وقد تجعل كناية عن المسنة بين\n⟦1:225⟧\nالنساء، فتذم به المرأة كما قال:\nوإن آتوك فقالوا إنها نصف\n.....\nفإن أمثل نصفيها الذي ذهبا\nوقيل: حرب عوان تشبيها بالمرأة، واستعارة منها كاستعارة القناة والشمطاء وغير ذلك من الأسماء، وقوله: ﴿لَّا فَارِضٞ﴾⟪2:68⟫ أي غير فارض، وهو وصف أو خبر ابتداء مضمر، كذلك عوان، لكن الأجود في عوان أن يجعل خبر ابتداء مضمر، فقد كثر عن الفراء الابتداء به وذلك قصد منهم أن يكون خارجا عن النفي في اللفظ كما هو خارج عنه في المعنى، وجاز أن يقال \" بين ذلك \"، وإن كان بين ذلك تضاف إلى شيئين لما كان ذلك عبارة عن الفارض والبكر في قوله: ﴿فَٱفۡعَلُواْ مَا تُؤۡمَرُونَ﴾⟪2:68⟫ زجر لهم عن المراجعة وتطلب العناد وتنبيه أن مراجعتهم تشدد الأمر عليهم وذلك كما روي عن النبي - صلى الله عليه وسلم - لما قيل له في الحج: العامنا هذا أم للأبد؟ فقال: بل للأبد ثم قال: (إئما أهلك من كان قبلكم بكثرة سؤالهم على أنبيائهم) .."}, {"a": [69], "v": 1, "p": 225, "ev": 1, "ep": 227, "sid": 226, "t": "قوله- عز وجل:\n﴿قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ صَفۡرَآءُ فَاقِعٞ لَّوۡنُهَا تَسُرُّ ٱلنَّٰظِرِينَ﴾⟪2:69⟫\nالآية (69) سورة البقرة.\nالصفرة لون مخصوص وعبر عن ذلك السواد بالصفرة، كما عبر عن الخضرة بالسواد، وذلك لكون الصفرة والخضرة سالكين إلي السواد، وقال الحسن.\nالصفراء هنا سوداء، لكن استبعد ذلك لقوله: فاقع، والسواد يقال فيه حالك لا فاقع، ولفظة الصفر يتصرف على وجهين، ومنه قيل للنحاس صفر وليبيس البهمى صفار، والثاني: حكاية صوت وهو الصفر، وعنه قيل: صفر الإناء إذا خلا حتى\n⟦1:226⟧\nيسمع منه صفير لخلوه، ثم صار متعارفا في الخالي، وقيل لخلو الجوف صفر وسعت العرب الصفر الذي هو الخلو حية الجوف من حيث انه يتألم به الجوف، وذلك أن العرق الممتد من الكبد إلى المعدة إذا لم يجد غذاء امتص أجزاء المعدة، فاعتقدت جهلة العرب أن ذلك حية في البطن تعض الشراسف، حتى نفى النبي- عليه السلام- ذلك بقوله: (لا صفر)، والسرور مستبطن في الصدر، وأصله من السرو، والسرور والحبور والفرح والجذل والمرح يتقارب، لكن السرور هو الخالص المتكتم، وسمي بذلك اعتبارا بالأسرار، والحبور ما يرى خبره أي أثره في ظاهر البشرة، وهما يستعملان في المحمود، وأما الفرح، فما يورث أشرا وبطرا، ولذلك كثيرا ما يذم فقال تعالى: ﴿إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ﴾⟪28:76⟫، وقال: ﴿وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪13:26⟫، والجذل بطر معه تزعزع، ولذللت قيل: \" فرس جذل وجذلان \"، أي نشيط، والمرح هو النشاط المفرط، فكأن السرور والحبور أكثر ما يكونان عن القوة الفكرية والفرح والجذل والمرح عن القوة الشهرية، ومن قال: ﴿تَسُرُّ ٱلنَّٰظِرِينَ﴾⟪2:69⟫ أي تعجب، فعلى التوسع من حيث إن الإعجاب بالشر والسرور به كثيرا ما يجتمعان.\n⟦1:227⟧"}, {"a": [70], "v": 1, "p": 227, "ev": 1, "ep": 228, "sid": 228, "t": "قوله عز وجل:\n﴿قَالُواْ ٱدۡعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ ٱلۡبَقَرَ تَشَٰبَهَ عَلَيۡنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ﴾⟪2:70⟫\nالآية (70) سورة البقرة.\nإن قيل: لم قال: ما هي؟ ولم يقل أي بقرة هي؟ أو كيف هي؟ وما يسأل به عن الأجناس، والأنواع، وإنما يسأل عن الأعراض بكيف وبأي؟ قيلت إنما قد يسأل به عن كل ذلك، فيقال: ما هذا الإنسان؟، أي ما حاله وما صفته، كما يقال كيف هذا الإنسان وأي إنسان هو؟ وكيف وأي لا يسأل بهما عن الأجناس والأنواع، والفصل بين ذلك أن لفظ ما من لفظة أي وكيف يجري مجرى الجنس من الأنواع، فكما يصح أن نعبر عن النوع بالجنس، فيقال للإنسان هو حيوان، ولا يصح أبو يعبر عن الجنس\nبالنوع، فيقال لكل حيوان إنسان، كذلك يصح أن يعبر عن أي وكيف بما، ولا يصح أن يعبر لكن كل ما فيه ما بأي وكيف، وقرئ \" تشابة \" على لفظ الماضي، فجعل لفظ البقر مذكرا، وتشابه بالتخفيف على تقدير تتشابه، فحذف إحدى ألتاءين وقرى \" تشابة \" بتشديد الشين على إدغام التاء في الشين، وقرئ \" يشابه \" بالتشديد على الإدغام والتذكير والاشتباه أن يشبه البعض البعض، فيصعب التمييز بينهما، وروى أنهم لما قرنوا بالمراجعة الأخيرة قولهما: ﴿وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهۡتَدُونَ﴾⟪2:70⟫ وفقهم الله لمعرفة\nما سالوا عنه ولترك التعنت، وقال النبي- عليه السلام- \" والذي نفس محمد بيده لو لم يستثنوا ما بينت لهم أخر الأبد \"، وفي ذلك حث، حيث قال الله تعالى لعباده على استجلأب توفيقه وضم لفظ المثنوية أي: مشيئة الله إلى كل ما يذكر من مستقبل الأمر كما قال: ﴿وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا ۝ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ﴾⟪18:23-24⟫\n⟦1:228⟧"}, {"a": [71], "v": 1, "p": 228, "ev": 1, "ep": 229, "sid": 229, "t": "قوله - عز وجل -:\n﴿قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٞ لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ وَلَا تَسۡقِي ٱلۡحَرۡثَ مُسَلَّمَةٞ لَّا شِيَةَ فِيهَاۚ قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُواْ يَفۡعَلُونَ﴾⟪2:71⟫ الآية (71) سورة البقرة.\nالإثارة.\nالبحث والكشف الشديدة ومنه ثار الدخان والغبار والقطاعن محثمها، والدم في وجه الإنسان والحصبة في البدن، وتورث الأمر، وقوله: ﴿تُثِيرُ ٱلۡأَرۡضَ﴾⟪2:71⟫ صفة لقوله: ذلول، لأنه يراد نفي الإثارة عنها لا إثباتها لها، والحرث تذليل الأرض وتسهيلها للزراعة، ثم يتجوز به في الزراعة، ويكنى به عن النكاح وعن جميع المال، ويقال: دابة محروثة أي مذللة، والمحراث لما يحرث الزرع والنار، والمسلمة المتروكة سليمة من العاهات، وأصل ذلك من السلامة، والتسليم أصله بذل السلامة، وجعل\nفي التعارف لبذل المقاله المخصوصة لما كان ذلك في الأصل موضوعا لبذل السلامة، ولما كان قوله السلام مقتضية لذلك، قال عليه السلام: \" أفشوا السلام بينكم تدخلوا جنة ربكم \" ولم يرد بذلك المقال دون الفعال وإن كان ظاهره المقال، ولهذا ضمن به الجنة، وقوله: ﴿لَّا شِيَةَ فِيهَاۚ﴾⟪2:71⟫ أي، لا أثر بها يخالف معظم لونها، وهي فعلة من الوشى، واستعمل الوشى في الكلام بالمنسوج وحض التقول على سبيل النميمة بالوشاية والمجئ والإتيان يتقاربان، لكن المجئ كأنه يقال باعتبار الحصول والإتيان باعتبار القصد، ولذلك قيل للماء المجتمع حية، وللسيل القاصد أتى، وقوله: ﴿قَالُواْ ٱلۡـَٰٔنَ جِئۡتَ بِٱلۡحَقِّۚ﴾⟪2:71⟫ لا يتضمن أن ما جئت به من قبل كان باطلا، وإنما أرادوا الآن جئت بما تحققنا المال منا، وليس كما قال بعض الناس إن القوم كفروا بذلك، لأن كلامهم تضمن أن موسى لم يكن يأتي بالحق قبله، والنفي في قوله: ﴿وَمَا كَادُواْ يَفۡعَلُونَ﴾⟪2:71⟫ وإن دخل في لفظ \" كاد \"، فهو متناول لقوله يفعلون نحو: ما كان زيد\n⟦1:229⟧\nيخرج، وتقدير ذلك كادوا يفعلون لتعذر ذلك عليهم وكثرة مراجعتهم، وقيل: (كادوا لا يفعلون) خشية الفضيحة.\nوأما أنهم بكم اشتروا البقرة، وممن اشتروها فليس مما يفتقر إليه تفسير الآية وقال بعض الناس: في هذه الآية دلالة على فسخ الشيء قبل فعله، فإن في الأول أمروا بذبح بقرة غير معينة، وكان لهم أن يذبحوا أي بقرة شاؤوا، وفي الثاني والثالث أمروا بذبح بقرة مخصوصة، فكأنهم نهوا عما كانوا أمروا به من قبل وليس الأمر كذلك، فإن الأول أمر مطلق، والثاني والثالث كالبيان له لما\nراجعوه ولم يسقط عنهم ذبح البقرة، بل ريد في أوصافها، وكشف عن المراد بالأمر الأول، وفي الآية دلالة على جواز تأخير بيان المجمل إلى وقت الحاجة .."}, {"a": [72, 73], "v": 1, "p": 229, "ev": 1, "ep": 232, "sid": 230, "t": "قوله- عز وجل:\n﴿وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا فَٱدَّٰرَٰءۡتُمۡ فِيهَاۖ وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ ۝ فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَٰلِكَ يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ﴾⟪2:72-73⟫.الآية (72، 73) سورة البقرة.\nادارأتم أي تدافعتم، وأصل الدرء الاعوجاج، فالتدارؤ أن يعوج كل على الآخر بمخالفته له، وقال الخليل: كوكب دري، فقيل من الدرء أي تدافع الضوء، ودرأت عنه الحد منه، ووزن \" ادارأتم \" من الفعل تفاعلتم، أصله تدارأتم، فأريد الإدغام تخفيفا، فأبدل من التاء دالا فسكن للإدغام، واجتلب لها ألف الوصل، فحصل على اتفاعلتم، وقال بعض الأدباء: ادارأتم افتعلتم، وكلما فيه من أوجه ...\nأولا: أن ادارأتم.\nعلى ثمانية أحرفا وافتعلتم على سبعة أحرف، وثانيا: أن الذي يلي ألف الوصل تا، فجعلها دالا، وثالثا: أن ألذي يلي الثاني دال، فجعلها تاء، ورابعا: أن الفعل الصحيح العين لا يكون ما بعد تاء الافتعال منه إلا متحركا، وقد جعله ههنا ساكنا وخامسأ: أن ههنا قل دخل بين التاء والدال زائد، وفي افتعلتم لا يدخل دلك، وسادسا: أنه أنزل الألف منزل العين وليست بعين،\nوسابعا: أن تاء افتعل قبله حرفان وبعده حرفان، وادارأ بعد التاء ثلاثة أحرفا وثامنا أن عين أفتعل في المستقبل مكسور، وبين \" ادرأتم \" في المستقبل مفتوح، وفي قوله: ﴿وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ﴾⟪2:72⟫\n⟦1:230⟧\nاعتراض متضمن لتمرد، وتنبيه أنه تعالى لا يخفى عليه خافية، وأن كل من عمل خيرا أو شرا، فإن الله تعالى لا يظهره على بعض الوجوه، وعلى ذلك روى \" ما عمل عبد حسنة في تسع آبيات إلا أظهره الله تعالى، لقوله: ﴿وَٱللَّهُ مُخۡرِجٞ مَّا كُنتُمۡ تَكۡتُمُونَ﴾⟪2:72⟫ ونظم هذه الآيات مشكل، فقد كان في الظاهر يقتضي أن يكون قوله: ﴿وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا﴾⟪2:72⟫ متقدما على قوله: (! از قال موسى لقومه ... )، لأن أمر موسى- عليه السلام- بذبح البقرة بعد التدارؤ، وفي قتل النفس والظاهر أن ذبح البقرة قد كان من\nقبل، وبيان ذلك أنه قد قيل قولان: أحدهما: أن موسي- عليه السلام- قد أمر بني إسرائيل أن يذبحوا بقرة قبل الحادثة، فلذلك تعجبوا وقالوا: أتتخذنا هزوا، فلما ذبحوا البقرة اتفق حصول القتال، فقال موسى لا راجعوه: \" اضربوه ببعضها \"، وقيل: بل كان الأمر بذبح البقرة بعد وقوع التشاجر، وعلى هذا قوله: ﴿وَإِذۡ قَتَلۡتُمۡ نَفۡسٗا﴾⟪2:72⟫ ليس بمعطوف على قوله: ﴿وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦٓ﴾، بل هو في موضع الحال له، كأنه قيل: (واذكروا إذ قال موسى لقومه .. ) الآية ..\nوذلك إذ قتلتم نفسا [فادارأتم فيها] أو إذ قتلتم نفسه كان ذلك، لكن اختصر، وفي قوله ﴿ٱضۡرِبُوهُ بِبَعۡضِهَاۚ﴾⟪2:73⟫ اختصار، كأنه قيل \" ليحى محي، وأنا بأي عضو ضرب، فقد قال مجاهد: بفخذها، وقال السدى: بمضغة من لحمها، وقال الفراء: بذنبها، وقال وهب: بأصغريها قلبها ولسانها، فظاهر الآية لا يقتضي تخصيص عضو، (من عضو) وقوله: ﴿يُحۡيِ ٱللَّهُ ٱلۡمَوۡتَىٰ﴾⟪2:73⟫، قيل: هو حكاية عن قول موسى\n-[عليه السلام]-\nلقومه، وقيل: بل هو خطاب من الله تلالي لهذه الأمة تنبيها على الاعتبار بإحيائه الموتى، وقد استبعد بعض الناس ذلك وماحكاه الله منه، وأنكر حصول ذلك الفعل على الحقيقة، وقال ذلك ممتنع من فعل الطبيعة، [وأيضا فإن ذلك لا يعرف فيه حكمة الشهية فأما\n⟦1:231⟧\nاستبعاده ذلك من حيث الطبيعة]، فإنما هو استبعاد للإحياء والنشور، ولذلك موضع لا يختص بالتفسير، ومن كان ذلك طريقته، فلا خوض معه في تفسير القرآن، وأما الحكمة فيه فظاهرة، إذ هو من المعجزات المحسوسات الباهرة للعقول، وتخصيص البقرة، فإن كثيرا من حكمة الله تعالى لا يمكن للبشر الوقوف عليه، ولو لم يكن في تخصيص بقرة على وصف مخصوص إلا توفر المأمور\nبذلك على طلبها واستيجاب الثواب في بذل ثمنها وجلب نفع إلى صاحبها لكان في ذلك حكمة عظيمة، وفي الآية تنبيه على أن الجماعة التي حكمهم واحد، يجوز أن ينسب الفعل إليهم وإن كان واقعا من بعضهم، ولا يكون ذلك كذبا، كما أن الجملة المركبة من شخص واحد يصح أن ينسب إليها ما وقع من عضو منها، وذكر بعض الصوفية أن الله تعالى قصد بما ذكره لبني إسرائيل وإشارة إلى معنى لطيف، فإن في الأمر بذبح البقرة أمرا بتذليل.\nالقوة الشهرية، ولما لم ينتبهوا لمراد ه، قالوا أتتخذنا هزوا.\nوبين قوله ﴿لَّا فَارِضٞ وَلَا بِكۡرٌ﴾⟪2:68⟫ أن حق الإنسان أن يتحرى في إماتة شهوته وقت ما يزول عنه شره صباه، فلا يكون كبكر، ولم يلحقه حسوا لكبر، فيكون كفارض، ثم نبه بما ذكره من اللون أنه لا يحب أن يمنع النفس من إماتة شهوته كونها رائقة المنظر، بل يجب أن يميتها أعجب ما تكون إليه، ثم نبه بقوله: ﴿لَّا ذَلُولٞ تُثِيرُ ٱلۡأَرۡضَ﴾⟪2:71⟫ أن النفس التي تحمل على تذليلها في العبادة هي النفس التي لم تستعبدها الدنيا ولم تتأثر بدنسها، ولم تتوسم بمقابحها، وطاهر الآية لا يقتضي ذلك، لكن مثله إذا حكى، فتصحيحه مفوض إلى فكرة قارئه ومتأملة، والله أعلم ..\n⟦1:232⟧"}, {"a": [74], "v": 1, "p": 232, "ev": 1, "ep": 235, "sid": 233, "t": "قوله - عز وجل -:\n﴿ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَٰلِكَ فَهِيَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةٗۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَٰرُۚ وَإِنَّ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ ٱلۡمَآءُۚ وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾⟪2:74⟫\nالآية: (74) سورة البقرة.\nقسا وحسا وعسا تتقارب معانيها- تقارب ألفاظها، فالقساوة تقال في الصلب الذي لا تخلخل فيه كالحجر ونحوه، وقيل: قلب قاس تشبيها به، وعسا إذا كان هدى معه عصيان فهو يقارب عصى، وحسا يقال فيما يتصلب، والصلابة تقال فيما في جوهره شدة، وأما الشدة فتقال فيما تعتبر فيه انضمام الأجزاء بعضها إلى بعض، ومنه قيل: شددته، وشد الشر الشيء واشتد، وقيل للعد والشد، كما يقال فيه القابض والتقريب والشدة تارة تقال في القوة الجسمية، وتارة في القوة النفسية، وقولهم: \" بلغ فلأن\nأشده \"، أي حاله استمر مرير نفسه وجسمه، والنهر يقال لمسيل الماء الواسع، وللماء جميعا ولتصور السعة.\nفيه يقال منه أنهرت فتقه، أي أوسعته، والنهار خص به السعة فيما بين طلوع الفجر إلى غروب الشمس، وألشق أن يجعل الشك شقين، وقيل للأخوين شقيقان، وللخلاف الشقاق، إذ هو ضد الائتلاف، والشقيقة في الداء تشبيها بذلك، ولهذا قيل له الصداع والخشية خوف عن تعظيم المخشى، وقد تقدم الفرق بينه وبين إخوانه والغفلة والسهو والنسيان يتقارب، لكن النسيان بانحذاف ذكر الشيء عن القلب والغفلة استتارة في بعض الأحوال اشتغالا بغيره، والسهو يقاربه، إلا أن الغفلة أكثر ما يقال فيما تركته وحقه أن لا يترك، والسهو يقال فيه وفيما فعلته ولم يكن حقه أن يفعل، فإذا السهو أعم من الغفلة واستعمل لأحد الشيئين، وقول من قال هو للشك فنظر منه إلى بعض تفاصيله، فإن الشك لا يقيده او بالقصد الأول، فقد يقال: لقيت زيدا أو عمرو قصدا إلى الإجمال والإبهام، أو لعله عنابه التفصيل، وقود بين الله تعالى بالآية أنهم ارتكبوا ذنوبا قست بها قلوبهم بعد آيات مقتضية للين\nقلوبهم من إحياء الفتى ومسخ الناس قردة وخنازير ورفع الطور فوقهم وأنها صارت في القساوة\n⟦1:233⟧\nبحيث إن قلت إنها كالحجارة قساوة صح بنظر، وإن قلت هي أشد من الحجارة صح بنظر، ثم ذكر حكما كليا، فقال \" وإن من الحجارة أي من القلوب القاسية التي هي كالحجارة، فذكر المشبه بلفظ المشبه به تحقيقا للتشبيه، كقولك: هم كالبقر ومن البقر ما يفعل كذا، أي من القوم الذين كالبقر، فكأنه قيل: وإن من القاسية قلوبهم من يراجع، فبعض يتفجر منه الأنهار، ومعناه حكمة بالغة كأنهار متفجرة، وبعض يتحصل منه نوع من العلوم يجري مجري الماء، وقد تقدم أن الماء يضرب به المثل في العلم، وبعض يحصل منه الخشية، ونبه بفحوى في الكلام أن هؤلاء المذمومين لم يحصل منهم شيء من ذلك فهم أحجار صلدة، وإنما قال: ﴿لَمَا يَتَفَجَّرُ مِنۡهُ﴾⟪2:74⟫، ولم يقل من اعتبار بلفظ الحجارة، وهذا الذي قلناه على قول من اعتبر هذه الأحكام في المشبه دون المشبه به، فأما من اعتبر ذلك في المشبه به دون الشبه، ففيهم من تعسف جدا في قوله: ﴿وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ﴾⟪2:74⟫ أي من الحجارة،\nومنهم من قارب، قال أبو علي الجبائي: عنى لهذه الحجارة البرد الهابط من السماء، وبقوله: ﴿مِنۡ خَشۡيَةِ ٱللَّهِۗ﴾⟪2:74⟫ أي بخشيته، وعنى بالخشية التخويف، لأن الخوف والخشية واحد، قال: \" ولما كان نزول البرد تخوفا ألفه لعباده قال ذلك، ثم قال، وإنما قلت هذا، لأن الحجارة جماد فلا يصح منه الخشية، كما ترى [قال الشيخ أبو القاسم- أيده الله]- فهذا كما ترى، وقال البلخي: هذا على جهة التمثيل لا في الحجارة من الانقياد لأمر الله الذي لو كان من حي قادر دل على أنه حاش لله ...\n، وقال بعضهم: وإن منها أي من الحجارة لما يهبط من أجل أن يخش الله العباد، وقال أبو مسلم ﴿وَإِنَّ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ ٱللَّهِۗ﴾⟪2:74⟫، الهاء فيه راجع إلى القلوب لا إلى الحجارة، أي من القلوب ما يخضع،\n⟦1:234⟧\nفيكون ذلك مستثنى من القاسية قلوبهم، ﴿وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ﴾⟪3:199⟫.وقال مجاهد وابن جريح كل حجر تردى من رأس جبل فخشية الله نزلت به، وقال الزجاج: الهابط منها قد جعل له معرفة، قال: ويدل على ذلك قوله: ﴿لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا مِّنۡ خَشۡيَةِ ٱللَّهِۚ﴾⟪59:21⟫، وقال: ألم تر أن الله يسجد له من في السموات ومن في الأرض إلى قوله: ﴿وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ﴾⟪22:18⟫، وقد روي مثل هذا عن السلف ولابد في معرفة ذلك من مقدمة تكشف عن وجه هذا القول، وحقيقته، فإن قوما استسلموا لا حكى لهم من هذا النحو، فانطووا على شبهة، وقومي استبعدوا ذلك واستخفوا عقل رواته وقائليه، فيقال وبالله التوفيق إن قوما من المتقدمين ذكروا أن جميع المعارف على أضرب، الأول: المغرفة التامة التي هي العلم التام وذلك لعلام الغيوب الذي أحاط بكل شيءعلما، والثاني: معرفة متزايدة، وهي للإنسان، وذاك أن الله تعالى جعل له معرفة غريزية، وجعل له بذلك سبيلا إلى تعرف كثير مما لم يعرفه، وليس ذلك إلا للإنسان، والثالث: معرفة دون ذلك وهي معرفة الحيوانات التي سخرها لإيثار أشياء نافعة لها والسعي أوليها واسترسال أشياء هي ضارة لها وتجنبها ودفع مضار عن أنفسها، والرابع: معرفة الناميات من الأشجار والنبات، وهي دون ما للحيوانات وليس ذلك إلا في استجلال النافع وما ينميها، والخامس: معرفة العناصر، فإن كل واحد منها مسخر، لأن يشعر المكان المختص به كالحجر في طلب السفر، والنار في طلب العلو ودلك له بتسخير الله تعالى لا باختيار منه، قالوا: والدلالة على ذلك أن كل واحد من هذه العناصر إذا نقل عن مركزه قهرا أبى إلا العود إليه طوعأ، قالوا: ويوضح ذلك أن السراج تجتذب الأدهان التي تبقيه ويأبى الماء الذي يطفيه، وأن المغناطيس\n⟦1:235⟧\nيجر الحديد ولا يجر غيره، هذا ما حكوه، فعلى هذا إذا قيل إن لهذه الأشياء معرفة، فليس ببعيد متى سلم لهم أن هده القوى تسمى معرفة، فأما إذا قيل إن للجمادات معارف الإنسان في أنها تميز وتختار وتريد، فهذا مما تعافه العقول، ونبه الله تعالى تخويفه لنا أن ارتكاب الذنوب يقضى براكبها إلى قساوة قلب حتى إنه ربما يعدم فيه رجاء الخيرات كلها، ونبه أنه تعالى لا يغفل عن أفعال البشر، إذ هو علام الغيوب .."}, {"a": [75], "v": 1, "p": 235, "ev": 1, "ep": 236, "sid": 236, "t": "قوله - عز وجل:\n﴿أَفَتَطۡمَعُونَ أَن يُؤۡمِنُواْ لَكُمۡ وَقَدۡ كَانَ فَرِيقٞ مِّنۡهُمۡ يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَمُونَ﴾⟪2:75⟫ الآية (75) سورة البقرة.\nالطمع يقارب الرجاء، والأمل، لكن الطمع أكثر ما يقال فيما يقتضيه الهوى والأمل والرجاء قد يكونان فيما يقتضيه الفكر والروية، ولهذا أكثر ذم الحكماء للطمع، حتى قيل الطمع طبع، والطمع يدنس الثياب، ويفرق الإهاب، والأصل في تحريف الشر الانتهاء به إلى ناحية يمكن جره إلى غيره، ثم يقال في كل كلام غير سكن وجهه محرف، والسماع يقال على ما يحس وعلى ما يتصور، ولذلك وصف الله تعالى الكفار بالصمم، فقوله: ﴿يَسۡمَعُونَ كَلَٰمَ ٱللَّهِ﴾⟪2:75⟫ حمل بعضهم على المسموع منه تعالى، فجعل الفريق بعض السبعين الذين كانوا مع موسى [عليه السلام] في المناجاة، لاستماع كلامه، فلما عادوا حرفوا ما سمعوه وإليه ذهب ابن عباس والربيع، وبعضهم حمله على ما كان في الأصل منه تعالي، وإن سمع من غيره فجعله التوراة وتجعل الفريق العلماء الذين غيروا التأويل، وإليه ذهب السدي والحسن وابن زيد، وفي الآية تسلية للنبي - صلى الله عليه وسلم - والمؤمنين، وتوهين للطمع في أئمتهم: وإن هؤلاء إذا كان علمائهم وأحبارهم الذين سمعوا لكلام الله وعقلوه وحرفوه ولم يؤمنوا، فكيف يرجى أن تؤمن جماعتهم مع جهل أكثرهم\nإن قيل: كيف يقتضى امتناع بعض من الإيمان\n⟦1:236⟧\nقطع الطمع في إيمان سائرهم؟ قيل: لما كان الإيمان هو العلم الحقيقي مع العمل بحاسب مقتضاه فمتى لم يتحر دلك من حصل له بعض العلوم، فحقيق أن لا يحصل لمن غنى عن كل العلوم، فذكر تعالى ذلك تبعيدأ لإيمانهم لابثأ للحكم بذلك، إذ ليس كل مالا يطمع فيه كان ميؤوسأ منه، وقوله: ﴿وَهُمۡ يَعۡلَمُونَ﴾⟪2:75⟫ أي يعلمون أنهم محرفون ومعاندون، وفي الآية تنبيه أن ليس المانع للإنسان عن تحري الإيمان الجهل به فقط، بل قد يكون عناده وغلبة شهوة .."}, {"a": [76], "v": 1, "p": 236, "ev": 1, "ep": 238, "sid": 237, "t": "قوله- عز وجل:\n﴿وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ قَالُوٓاْ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ﴾⟪2:76⟫ الآية (76) سورة البقرة.\nالحديث ما يوجد بعد ان لم يكن نطقا كان أو عينا، والفتح أصله فتح الغلق، ولما استعمل في الأمر المبهم والكلام الصعب الغلق استعمل في إزالته الفتح، ومنه قيل في الحرب وفي آيات الحجة، وفي الحكم الفتح حتى قيل للحكم المفصول فتاحة، وللحاكم فتاح، وقوله: ﴿بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ﴾⟪2:76⟫ أي بما أطلعكم عليه من العلم، وهذا أولى من قول [من قال]: ﴿بِمَا فَتَحَ ٱللَّهُ عَلَيۡكُمۡ﴾⟪2:76⟫ من النصر في مغازي رسول الله - صلى الله عليه وسلم - ومن الآيات التي كانت في بدر من المواضع التي انتهى إليها فبدل وقوع\nالحرب، فقال: [هذا مصرع فلان غدا، وهذا مصرع فلأن]، ثم كان على ما قال، فإن هذا لم\n⟦1:237⟧\nيخصهم النبي- عليه السلام- بالاطلاع عليه دون المؤمنين، حتى كانوا يكتمونه ويتواصوا به، والحجة هي ما يقتضي صحة أحد النقيضين، وأصله من الحج أي القصد للزيادة، وسمى سبر الجراحة حجا، وخلا فلأن أي صار في خلاء، فالآية إخبار عن المنافقين منهم، وأنهم يظهرون الإيمان ويتواصون فيما بينهم أن لا يظهروا ما انكشف لهم من حقائق النبوة لئلا يصير ذلك حجة عليهم في حكم الله، وهدا معنى قوله: ﴿عِندَ رَبِّكُمۡۚ﴾⟪2:76⟫، كقوله ﴿فَأُوْلَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ﴾⟪24:13⟫ أي في حكمه، وهدا التأويل أولى من قول من قال: ﴿لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ﴾⟪2:76⟫ أي يوم القيامة، وقيل: ﴿عِندَ رَبِّكُمۡۚ﴾⟪2:76⟫ أي: عند سيدكم يوم الخصام، وقوله: ﴿أَفَلَا تَعۡقِلُونَ﴾⟪2:76⟫ يصح أن يكون من جملة الحكاية عنهم على سبيل إنكار بعضهم على بعض، ويصح أن يكون استئناف إنكار من الله - عز\nوجل-[عليهم] على سبيل ما يسمى في البلاغة ب \" الالتفات \"، ويصح أن يكون ذلك خطابا للمؤمنين تنبيها على ما يفعله الكفار والمنافقون.\n⟦1:238⟧"}, {"a": [77], "v": 1, "p": 238, "ev": 1, "ep": 238, "sid": 239, "t": "قوله - عز وجل -:\n﴿أَوَلَا يَعۡلَمُونَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ﴾⟪2:77⟫ الآية: (77) سورة البقرة.\nهذا تبكيت لهم وإنكار لما يتعاطونه مع تكلمهم أن الله لا يخفى عليه خافية."}, {"a": [78], "v": 1, "p": 238, "ev": 1, "ep": 240, "sid": 239, "t": "قوله - عز وجل -:\n﴿وَمِنۡهُمۡ أُمِّيُّونَ لَا يَعۡلَمُونَ ٱلۡكِتَٰبَ إِلَّآ أَمَانِيَّ وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ﴾⟪2:78⟫ الآية: (78) سورة البقرة.\nالأمي: قيل هو الذي لا يكتب، وأصل هذا اللفظ في المنسوب إلى الأم، ولما كانت الأم هي المنشئة المربية للولد، تصور ذلك في أشياء، فقيل له أم نحو أم الأضياف، وأم الجيش للرئيس، وأم القرى لمكة وذلك لنحو ما روى أنه لا خلق الأرض دحاها من تحت الكعبة، وأم الكتاب للوح المحفوظ ولفاتحة الكتاب تصورا أن منهما منشأ الكتاب، وقيل أمه إذا قصده قصد الإنسان للأم المشفقة عليه، ومنه اشتق الإمام والأمة، فالأمي في التعارف هو المنسوب إلى ما يجري منه مجرى أمه في العناية وتربيته في الفضيلة وحفظها عليه أما ما كان ذلك أو غيره، واستعمل فيمن لا يقرأ فيحتاج إلى من يحفظ عليه معارف، وهذه الحالة فضيلة للنبي- عليه السلام- ونقيصة لغيره، من أجل أنه- عليه السلام- حفظ عليه علومه فيض إلا هي ونور سماوي، فصار افتقاره غني، كما روى [عنه - صلى الله عليه وسلم -] أنه كان يقول في دعائه:\n\" اللهم اغنني بالافتقار إليك \"، وغيره لما احتاج إلى أن يحفظ معلومه عليه آدمي مثله صار في الحقيقة ناقصة، وفقيرا وقوله: ﴿إِلَّآ أَمَانِيَّ﴾⟪2:78⟫، الأصل في هده اللفظة الدائر في جميع متصرفاته التقدير، ومنه المنا الذي يوزن به، والذي الذي منه الحيوان، ومنى الله كذا، أي قدر، وعن ذلك\n⟦1:239⟧\nوضع الأمنية، فإنه تقدير شيء في النفس وتصويره فيها، وذلك قد يكون عن تخمين وظن، ويكون عمن روية وبناء على أصل، لكن لما كان أكثره عن تخمين صار الكذب به أملك، فأكثر التمني تصور ما لا حقيقة له، ولا كان الكذب تصور ذلك ويراد باللفظ صار التمني كالمبدأ للكذب، فيصح أن يعبر عن الكذب بالتمني في نحو ما روي عن عثمان- \" رضي الله تعالى عنها \" - أنه قال: \" ما تغنيت ولا تمنيت \"، ولما قلناه قال مجاهد: \" إلا أماني \" معناه \" إلا كذبا \"، وقال غيره: ألا تلاوة مجردة عن المعرفة من حيث أن التلاوة بلا معرفة العنف تجري عند صاحبها مجري أمنية مبنية على التخمين،\nفإن قيل: فما معنى قوله تعالى على هذا: ﴿وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ﴾⟪22:52⟫ قيل: قد قلنا إن التمني كما يكون عن تخمين وظن، فقد يكون عن روية وبناء على أصل، ولما كان النبي- عليه السلام- كثيرا ما كان يبادر إلى ما نزل به الروح الأمين على قلبه حتى قيل له: ﴿وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ﴾⟪20:114⟫ ﴿لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ﴾⟪75:16⟫ سمي تلاوته على ذلك تمنيت ..\n، وقوله: ﴿وَإِنۡ هُمۡ إِلَّا يَظُنُّونَ﴾⟪2:78⟫ كناية عن الكذب لما كان الظن واقعا بين الصدق والكذب، كما كنى عنه بالحرص الذي هو تقدير الأثمار لما كان ذلك مترددا بين الوفاق والخلاف، وقد أنبأ الله تعالى بالآية عن جهل الأميين وذمهم والمبالغة في ذم علمائهم وأحبارهم، فإن الأميين لم يعرفوا إلا مجرد التلاوة، واعتمدوا على زعمائهم وأحبارهم، وهم قد ضلوا وأضلوا، ونبهنا الله تعالى\nبذم الأميين على اكتساب العارف لئلا يحتاج إلى التقليد والاعتماد على من لا يؤمن كذبه وبذم زعمائهم على تحري الصدق وتجنب الإضلال، إذ هو أعظم من الضلال ..\n⟦1:240⟧"}, {"a": [79], "v": 1, "p": 240, "ev": 1, "ep": 242, "sid": 241, "t": "قوله - عز وجل -:\n﴿فَوَيۡلٞ لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ ثُمَّ يَقُولُونَ هَٰذَا مِنۡ عِندِ ٱللَّهِ لِيَشۡتَرُواْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَوَيۡلٞ لَّهُم مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡلٞ لَّهُم مِّمَّا يَكۡسِبُونَ﴾⟪2:79⟫ الآية (79) سورة البقرة.\nويل: تقبيح، وقد يستعمل على سبيل التحسر، وما روى أبو سعيد الخدري- \" رضي الله عنه \" - أنه واد في جهنم، فليس يعني أن الويل هو اسم لذلك الوادي، وإنما يعني أن الذين يجعل لهم الويل هم المتبوئون في ذلك الوادي، والكسب استجلاب نفع، وقوله: ﴿وَمَن يَكۡسِبۡ خَطِيٓـَٔةً﴾⟪4:112⟫، فعلى نحو قوله: ﴿فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ﴾ إن قيل ما وجه توكيد الكتابة باليد، وهي لا تكون إلا بها،\nقيل: لما كانت اليد العاملة يختص بها الإنسان من بين الحيوان وهي أعظم جارحة، بل عامة المنافع راجعة إليها حتى لو توهمناها مرتفعة ارتفع بها الصناعات التي بها قوام العالم كالبناء، والحوك، والصوغ صارت مستعارة في القوى جميعا، والمنافع كلها حتى قيل: فلان يد فلان إذا قواه، وقيل للنعمة يد لما صارت معينة للمعطى إعانة يده وحتى صار مستعارا في اللفظ لله تعالى بدلا عن القدرة أو عن النعمة أو صفة أخرى غيرهما، فذكرت مثناة مرة ومجموعة مرة تصويرا للمبالغة في ذلك، فقال\nتعالى: «والسماء بنيناها بأيد»، وقال تعالى: ﴿مِّمَّا عَمِلَتۡ أَيۡدِينَآ﴾⟪36:71⟫، وقال: ﴿لِمَا خَلَقۡتُ بِيَدَيَّۖ﴾⟪38:75⟫، ووجه آخر، وهو أن الفعل ضربان: ابتداء، واقتداء، فيقال فيما كان ابتداء: \" هذا مما عملته يدي فلان \"، فقوله: ﴿مِّمَّا كَتَبَتۡ أَيۡدِيهِمۡ﴾⟪2:79⟫ أي مما اخترعوه من تلقائهم، وعلى هذا قد يحمل قوله تعالى:\n⟦1:241⟧\n﴿يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ﴾⟪3:167⟫، إن قيل \" لم ذكر يكسبون بلفظ المستقبل، وكتبت أيديهم بلفظ الماضي؟ قيل: تنبيها على أن ما قال النبي- عليه السلام- \" من سن سنة حسنة فله أجرها وأجر من عمل بها ومن سن سنا سيئة فعليه وزرها ووزر من عمل بها إلى يوم القيامة، فنبه بالآية أن ما أضلوه وأثبتوه من التأويلات الفاسدة التي يعتمدها الجهلة هو اكتساب وزر يكتسبونه حالا فحالا إن\nقيل: لم ذكر الكتابة دون القول؟ قيل: لما كانت الكتابة متضمنة للقول وزائدة عليه إذ هو كذب باللسان\nواليد صار أبلغ، لأن كلام اليد يبقى رسمه، والقول يضمحل أثره ...\nإن قيل ما الذي كانوا يكتبون؟\nقيل: قد روي عن بعض السلف أن رؤساء اليهود كانوا يغيرون من التوراة نعت النبي - صلى الله عليه وسلم -، ثم يقولون\nهذا من عند الله، وهذا فصل يحتاج إلى فضل شرح، وهو أنة يجب أن يتصور أن كل نبي أتى بوصف لنبي بعده فإنه أتى بلفظة معوضة به وإشارة مدرجة لا يعرفها إلا الراسخون في العلم وذلك لحكمة ألاهية، فإن من شأن المسوسين سيما الذين لم يتمهروا في الحقائق أنهم متى أحسوا بحال سايس يتعقبه \" سايسهم \" وإمامهم تواكلوا عن الأئتمار لأوامره، والأرتسام لزواجره، وهذا معروف من عادات الناس، وقد قال العلماء ما انفك كتاب منزل من السماء من تضمن ذكر النبي عليه السلام، ولكن بإشارات ولو كان دلك متجليا لعوام لما عوتب علماؤهم في كتمانه، ثم ازداد ذلك غموضأ بنقله من لسان إلى لسان من العبراني إلى السرياني \" ومن السرياني \" إلى العربي، وقد ذكر المحصلة ألفاظا من التوراة والإنجيل إدا اعتبرتها وجدتها دالة على صحة لنبوة محمد - صلى الله عليه وسلم - بتعريض هو عند الراسخين في العلم جلي، وعند العامة خفي، فبان بهذه الجملة أن ما كتبت أيديهم كان تأويلات محرفة، وقد نبه الله تعالى بالآية على التحذير من تغيير أحكامه وتبديل آياته وكتمان الحق عن أهله وترك الأمر بالمعروف والنهي عن المنكر طمعا في عرض من أعراض الدنيا، وقد تقدم أنه قد عنى بالثمن القليل أعراض الدنيا وإن كثرت لقوله تعالى: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾⟪4:77⟫.\n⟦1:242⟧"}, {"a": [80], "v": 1, "p": 242, "ev": 1, "ep": 243, "sid": 243, "t": "قوله - عز وجل -:\n﴿وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدٗا فَلَن يُخۡلِفَ ٱللَّهُ عَهۡدَهُۥٓۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾⟪2:80⟫ الآية: (80) سورة البقرة.\nالمس واللمس والحس والجس تتقارب، إلا أن الحس عام في المحسوسات والجس فيما يخفى ويدق كنبض العرق والخبر الخفي، واللمس بظاهر البشرة، وكل ذلك يقال عند تأثير المحسوس في المس وبغيره لأجله، واللمس كالطلب للمس ، وقد ينفك منه، ولذلك قال: \" وألمسه فلم أجده \"، وجعل المس كناية عن النكاح تارة، وعن الجنون تارة، فقيل: بفلان مس، وهو ممسوس، والمسوس من الماء ما مسته الأيدي، ولا كانوا كل وعد عقدا ما وكل عقد عهدا ما كان كل وعد عهدا، فصح أن يعبر عن\nالوعد بالعهد، ولكونه وعدأ استعمل منه الإخلاف، ومعدودة قليلة ووجه ذلك أنه لما كان المعدود ضربين، ضربا قليلا يسهل عده (وإحصاؤه) وكثيرة لا يسهل عده، وكانت الأعراب يقل فيهم الحساب وقوانين الحساب، تصوروا الكثير متعذر العد، والقليل متيسر العد، وقالوا: \" شي معدود ومحصور أي قليل وغير معدود، ومحصور أي كثير.\nووجه الآية أن اليهود اختلفت، فبعض قال نعذب بعدد الأيام التي عبد أصحابنا فيها العجل، وبعض قال: مدة الدنيا سبعة ألاف سنة وإنما نعذب مكان كل ألف\nسنة من الدنيا يوما من الآخرة، وبعضه قال: إنما بين طرفي جهنم أربعون سنة، وإذا خلا العدد انقضى الأجل ولا عذاب، فبين الله تعالى أن زعمكم أنا نعذب أياما معدودة ولا طريق للعقل إلى معرفة ذلك، وإنما سبيل معرفته الإخبار عنه تعالى.\nجده-، وإخباره بذلك وعد، ووعده عهد، وما كان به من الله- عز وجل من عهد فلا خلف فيه، وقد تبت أنه لا عهد له بذلك، فإذا ليس هو إلا تقولا منكم على الله بما لا تعلمون، فبين بلفظ الاستفهام كذبهم فيما زعموا، وقوله: \" عند الله \"، أي في حكمه على\nما تقدم ...\n⟦1:243⟧"}, {"a": [81], "v": 1, "p": 243, "ev": 1, "ep": 245, "sid": 244, "t": "قوله - عز وجل -:\n﴿بَلَىٰۚ مَن كَسَبَ سَيِّئَةٗ وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:81⟫\nالآية: (81) سورة البقرة.\nبلى: رد للنفي، ونعم عدة وتصديق، ويقعان في الاستفهام والخبر، فبلى لا يكون إلا في النفي، أما في الاستفهام فنحو قوله ﴿أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ﴾⟪7:172⟫، وأما في الخبر فنحو: هذا، وأما نعم ففي الاستفهام نحو: ﴿فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ﴾⟪7:44⟫، ويقال: أنا أحبك، بل نعم ولا يقال: بلى بوجه، وفي النفي إدا قيل ما عندي شي، فقلت بلى، فهو رد لكلامه، وإذا قلت: نعم فإقرار منك به، والسيئة الفعل القبيح القيود إليه في نفسه ولكونها قبيحة قوبلت بالحسنة في عاهة ما جاء في القرآن، نحو: ﴿مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ﴾⟪6:160⟫ الآية وقوله ﴿وَبَلَوۡنَٰهُم بِٱلۡحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ﴾⟪7:168⟫، وقوله ﴿وَيَسۡتَعۡجِلُونَكَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ﴾⟪13:6⟫ وقوله: ﴿وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ﴾⟪41:34⟫ والفرق بينها وبين الخطيئة أن السيئة قد يقال فيما يقصد إليه في نفسه، والخطيئة أكثر ما تقال فيما لا يكون مقصودا إليه في. نفسه، بل يكون مقصودا إلى سببه كمن يرمي صيدا، فأصاب سهمه إنسانا أو شرب مسكرا، فجني على رجل جناية في سكره، ثم السبب في دلك سببان، سبب محظور فعله، كشرب المسكر، وسبب غير محظور،\n⟦1:244⟧\nفقيل في الأول الخطأ، وقد أخطأوا في الثاني خطأ، وقد خطى فهو خاطئ، وعلى هذا ﴿وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ﴾⟪33:5⟫ وقال: ﴿لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ﴾⟪69:37⟫، وفي استعارة الاحاطة أبلغ تشبيه، وذاك أن الإنسان إدا ارتكب ذنبا فلم يقلع عنه استجرت إلى معاودة مثله، ومعاودة مثله تجعل على قلبه غشاوة، فتجر به إلى ارتكاب أكبر منه، ثم ارتكابه لا هو أكبر منه يطبع على قلبه، فيشجعه على المداومة عليه، فيصير ذلك عليه حائطا يمنعه عن رؤية ما وراء، فيرى في مقابح الذنوب محاسن، فيتخبط في بلايا من دنياه ربما يراها نعما، فيحسب أن لا وراء اللذات الدنيوية لذة ولا بعد التخصيص بقاء وورائها نعما فهذا معنى: ﴿وَأَحَٰطَتۡ بِهِۦ خَطِيٓـَٔتُهُۥ﴾⟪2:81⟫، وعلى ذلك دل قوله تعالى: ﴿ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ﴾⟪30:10⟫، وقوله: ﴿فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ﴾⟪9:77⟫، ووجه أخر روى عن السلف وهو إن كان عائدا إلي ما تقدم، فالنظر إليهما مختلف، وهو أن السيئة الكفر، وذلك عن مجاهد وأبي وائل والربيع، فبين تعالى أن من تحرى طريق الكفر، ثم استمر مريرة في ترك الإقلاع إما الترك النظر، وإماما الشرارة، وإماما لشهوة مستولية عليه حتى يصير ذلك كحائط عليه لا خروج له منه، فأولئك أصحاب النار، ومن قرأ (خطيئته)، فاعتبارا بالجنس، ومن قرأ (خطيئاته)، فاعتبارا بآحاد الذنوب وجعلهم أصحاب النار لملازمتهم في الدنيا ما يوجب لهم النار، وهي الآخرة لملازمتهم إياهما إذ كان الصاحب إنما يقال فيمن كثر ملازمته لغيره ...\n⟦1:245⟧"}, {"a": [82], "v": 1, "p": 245, "ev": 1, "ep": 245, "sid": 246, "t": "قوله - عز وجل -:\n﴿وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:82⟫\nالآية: (82) سورة البقرة.\nعادة القرآن في كل موضع يذكر عقاب قوم أن يذكر بإزائه ثواب مضادتهم ليرجى رحمته ويخاف عذابه، وقد تقدم أن عامة ذكر الإيمان في القرآن مقرونة بالأعمال الصالحة تنبيها أن جملة الاعتقاد والمقال لا اعتداد بها ما لم يضامها الأعمال الصالحة، إذ الاعتقاد كالأس، والعمل كالبناء، ولا غناء في أسء بلا بناء، كما لا ثبات لبناء بلا أس، وفيه دلالة أن قوله تعالى من قبل: ﴿بَلَىٰۚ مَن كَسَبَ سَيِّئَةٗ﴾⟪2:81⟫ هو الكفر، وإحاطة الخطيئة به الأعمال السيئة، وذلك لا قابله به من الإيمان والأعمال الصالحة .."}, {"a": [83], "v": 1, "p": 245, "ev": 1, "ep": 248, "sid": 246, "t": "قوله - عز وجل -:\n﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ﴾⟪2:83⟫\nالآية (83) سورة البقرة.\nالولد: المولود، والوليد للصبي اعتبارا بقرب ولادته، كما يقال: لما قرب اجتناؤه جني، والوليدة في الأمة كناية عن طريق التلطف بأنها تجري مجرى الولد، و \" فلان لدة فلأن \"، أي ولد معه، واليتيم قد يقال لمن فقد كافله قبل البلوغ من أبويه، أما في الناس فأباه، وأما في البهائم فأمه، لأن كفالة الولد في الناس على غالب الأمر، وفي الحكم إلى الأب، وفي البهائم إلى الأم، وقد يقال لن يتصور بصورة الفرد الذي إذا اعتبرت فضيلته قدر أن لا أباله من جنسه لكونه خارجية بالفضل عن طبيعة أبائه،\n⟦1:246⟧\nوجدك فاصطفاك، كقوله تعالى في موسى عليه السلام: ﴿وَٱصۡطَنَعۡتُكَ لِنَفۡسِي﴾⟪20:41⟫، وأخذ هذا الميثاق المذكور في الآية ليس شيئا اختص به بنو إسرائيل فقط، بل في كل أمة، ولكل نبي، وقد تقدم أن هذه العبادات مما لا يجوز خلو شرع منها وإن اختلفت هيئاتها وأعدادها وأن كلياتها مأخوذة على الناس بقضية عقولهم وألسنة أنبيائهم وجزئياتها وكيفياتها مأخوذة عليهم بألسنة أنبيائهم- عليهم السلام - إذ لا طريق للعقل إلى صرفة جزئيات العبادات والصالح المعلقة بها، وليس أخذ الميثاق\nكله معتبرا بان يلتزمه المأخوذ عليه ويرضى به، بل بأن توجه الحجة، وتقدير قوله: ﴿لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ﴾⟪2:83⟫ فيه أوجه، قال الكسائي: ﴿أَن لَّا تَعۡبُدُوٓاْ﴾، فلما حذف \" أن \" نرفع، نحو:\nألا أيهذا الزاجري أحضر الوغى\nوقال الأخفش: لما أفاد قوله ﴿أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ﴾⟪2:83⟫ معنى القسم أجابه بجوابه نحو: خلفت لا يخرج زيد، وقال قطرب: (لا تعبدون) في موضع الحال، تقديره غير عابدين، وقال الفراء: لفظه خبر، ومعناه النهي نحو: ﴿لَا تُضَآرَّ وَٰلِدَةُۢ بِوَلَدِهَا﴾⟪2:233⟫ بالرفع، واستدل على كونه نهيأ بقراءة أبي: ﴿أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۚ﴾، وبعطف قوله: ﴿وَقُولُواْ لِلنَّاسِ حُسۡنٗا﴾⟪2:83⟫ عليه.\n⟦1:247⟧\nولما تضمن أخذ الوثاق معنى الوصية حمل عليه قوله: ﴿وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا﴾⟪2:83⟫ واختلف في قوله تعالى: ﴿وَقُولُواْ لِلنَّاسِ حُسۡنٗا﴾⟪2:83⟫، فذهب بعضهم إلى أنه منسوخ بأية السيف، لأن المسلمين أمروا في الارتداء أدت يتلقوا الكافر أو المسلم بالحسنى، ثم أمروا بالتغليظ والقتال، وقيل: لا نسخ فيه وهو الأصح، لأن ذلك كقوله: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ﴾⟪16:125⟫ لآية، ولأن قتالهم لا يمنع من أن يقاد لهم أولا قول حسن، كما قاد موسى- عليه السلام- ﴿فَقُولَا لَهُۥ قَوۡلٗا لَّيِّنٗا﴾⟪20:44⟫، ثم قوله: ﴿وَقُولُواْ لِلنَّاسِ حُسۡنٗا﴾⟪2:83⟫، يصح أن يكون نهيا عن المقادح والكذب، ثم هذه الاية ليست خطابا للمسلمين من هذه الأمة، وإنما هي حكاية ما أمر به بنو إسرائيل، وهما خطاب للأسلاف من بني إسرائيل، وقيل:\nهو خطاب لن كان في زمان رسول الله - صلى الله عليه وسلم - منهم، وقيل قوله: ﴿ثُمَّ تَوَلَّيۡتُمۡ﴾⟪2:83⟫ خطاب للسلف، وقوله: ﴿وَأَنتُم مُّعۡرِضُونَ﴾⟪2:83⟫ خطاب لمن كان في زمنه،\nإن قيل: ما فائدة قوله: ﴿وَأَنتُم مُّعۡرِضُونَ﴾⟪2:83⟫ بعد قوله:.\n﴿ثُمَّ تَوَلَّيۡتُمۡ﴾⟪2:83⟫ قيل فيه ثلاثة أقوال، الأول: أن قوله ﴿وَأَنتُم مُّعۡرِضُونَ﴾⟪2:83⟫ حال مؤكدة، لأن تقديره: (ثم توليتم معرضين)، ذلك على قول من جعلها خطابا لفريق واحد، والثاني أن التولي قد يكون لحاجة تدعو إلى الانصراف مع ثبوت العقد والإعراض هو الانصراف عن الشيء بالقلب، والثالث: أن التولي والإعراض في دلك مثل مأخوذ من سلوك الطريق، وإدا اعتبرنا حال سالك المنهج في ترك سلوكه، فله حالتان، إحداهما: أن يرجع عوده على بدئه، وذاك هو التولي، والثانية: أن يترك النهج ويأخذ في\n⟦1:248⟧\nعرض الطريق متخطيا، وذلك هو الإعراض والمتولي أقرب أمرا من المعرض، ولأنه متى ندم على رجوعه سهل عليه العودة إلى سلوك المنهج، وأخذ في عرض المفازة إلى طلب منهجه، فيعسر عليه العود إليه، فمتى جعل الخطبان لفريق واحد، فذلك غاية الذم، فإنهم جمعوا بين العود عن السلوك والإعراض عن المسلك، ومتى جعل \" توليتم \" للسلف، وأنتم معرضون للخلف، فتنبيه أنكم شر من أسلافكم، فقد كان منهم التولي، ومنكم الإعراض، والآية منطوية على عامة الأحكام الاعتقادية والعلمية والآداب الشرعية ومكارم الأخلاق، وفيها ذم لبني إسرائيل أن مع أخذ الميثاق منهم بذلك لم يكن من أكثرهم الوفاء به .."}, {"a": [84], "v": 1, "p": 248, "ev": 1, "ep": 249, "sid": 249, "t": "قوله - عز وجل -:\n﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ لَا تَسۡفِكُونَ دِمَآءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ﴾⟪2:84⟫\nالآية (84) سورة البقرة.\nالدار سميت اعتبارا بدورها، وقيل داره، كقولهم: محلة ومنزلة اعتبارا بوحدة ما، فإن الدار يقال لها وإن انطوت على حجر وبيوت، والدواري الدهر، لكر الجديدين، والدوار في الرأس وضم على بناء الأدواء، نحو الصداع، يقال للصنم التي يدار حوله دوار ودوار ودوار، وقوله تعالى: ﴿لَا تَسۡفِكُونَ دِمَآءَكُمۡ﴾⟪2:84⟫ متعلق بقوله: ﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ﴾⟪2:84⟫ ما تقدم في الآية الأولي ..\nإن قيل: كيف أخذ ميثاقهم أن لا يفعلوا ذلك بأنفسهم مع كون الإنسان مضطرا لأن يفعل بها ذلك؟، قيل في ذلك أجوبة ...\nالأول: لا يفعل ذلك بغضكم ببعض، وإليه ذهب قتادة وأبو العالية، الثاني: لا يفعلن أحدكم [ذلك] بالآخر، فيفعل به، فيكون في حكم فاعله بنفسه، الثالث: [لا تفعلوا ما يؤدي بكم إلى صرفكم عن الحياة الأبدية الجاري مجرى القتل، وهو العذاب الأليم]، ولا تفعلوا ما تحرمون به على أنفسكم\n⟦1:249⟧\nالجنة التي هي داركم فتكونوا في حكم من أخرج نفسه من داره، وعلى ذلك قوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾⟪4:29⟫، وعلى هذا حمل قوله تعالى: ﴿قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ﴾⟪6:140⟫ أي: شغلوهم بما يعود بوبالهم وحرموا العلم، والإقرار قد، يكون باللفظ ويكون بالفعل وهو الرضى، نحو أن يقال: فلان مقر بالخسف ..\nقال الشاعر: ..\nأقر كما قر الخليلة للبعل ..\nفقوله ﴿أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ﴾⟪2:84⟫ يصح أن يكونا [جميعا خطابين] للسلف، وأن يكونا للخلف [وأن يكون الأول للسلف والآخر للخلف]\nفإن قيل: ما الفرق بين الإقرار والشهادة؟ قيل: الشهادة إقرار مع العلم وثبات اليقين، والإقرار قد ينفك من ذلك، ولهذا كذب الله تعالى الكفار في قولهم: ﴿نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾⟪63:1⟫ ولو قالوا: نقر إنك لرسول الله لم يكذبوا .."}, {"a": [85], "v": 1, "p": 249, "ev": 1, "ep": 253, "sid": 250, "t": "قوله - عز وجل:\n﴿ثُمَّ أَنتُمۡ هَٰٓؤُلَآءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِيقٗا مِّنكُم مِّن دِيَٰرِهِمۡ تَظَٰهَرُونَ عَلَيۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَٰبِ وَتَكۡفُرُونَ بِبَعۡضٖۚ فَمَا جَزَآءُ مَن يَفۡعَلُ ذَٰلِكَ مِنكُمۡ إِلَّا خِزۡيٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾⟪2:85⟫ الآية: (85) سورة البقرة.\nقيل: تقدير هؤلاء يا هؤلاء، وذلك مستبعد لحذف حرف النداء، [فحرف النداء] لا يحذف إلا من الأعلام وما هو كالأعلام ومن المضاف دون غيرهما من المناديات، وقيل معناه كمعنى الذين، فقد أجرى\n⟦1:250⟧\nالمبهمات مجرى الموصولات، وعلى ذلك حمل الكوفيون قوله تعالى: ﴿وَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ﴾⟪20:17⟫ وقول الشاعر:\nنجوت وهذا تحملين طليق\nوقيل معناه: أنتم كهؤلاء، وتظاهرون تتعاونون، وأصل اللفظة من الظهر التي هي الجارحة، ولما كان الظهر من حيث الخلقة خاليا عن الحروق والعكن بخلاف البطن، سمي ما كان بارزا ظهرا، وما كان خافيا بطنا، فجعل الظهر والظهور لجميع متصرفات هذه اللفظة أصلين وقرئ تظاهرون بالتشديد، وأصله: يتظاهرون ويظاهرون بالياء والتشديد على ذلك، وتظاهرون بحذف أحد ألتاءين وبالتخفيف، والإثم اسم الأفعال المبطئة للثواب، ولتضمن البطؤ قال الشاعر في صفة ناقة:\nجمالية تعتلي بالردف\n....\nإذا كذب الآثمات الهجير\nوقوله تعالى: ﴿قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ﴾⟪2:219⟫ أي في تعاطيهما أبطأ عن الخيرات، فإنهما شاغلان، فصار الإثم في التعارف نقيض البر\n⟦1:251⟧\nوقوله عليه السلام:\n\" البر ما اطمأنت إليه النفس، والإثم ما حاك في صدرك \"، فهذا حكمهما لا تفسيرهما والوزر والذنب والجرم تتقارب، لكن الوزر اسم لا يوجب العقوبة بمعاونة الغير، ولهذا روى:\n\" من سن سنة سيئة فله وزرها ووزر من عمل بها \"، فإن السان والمسنن بها متآزران متعاضدان، والسان أعظم إثما، إذ ليس المتبع كالمبتدع، وأما الذنب فما يقتضي عاقبة مذمومة اعتبارا بأذناب الأمور، والجرم اعتبارا بما يحصل من ثمرة سوء العمل تشبيها لجرام النخل، والعدوان هو تجاوز لحد المرسوم في الاعتداء المرخص فيه على سبيل المجازاة في قوله: ﴿فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ﴾⟪2:194⟫ فالتجاوز للمرسوم هو العدوان، والأسر شد يضم به بعض المشدود إلى بعض يقال: أسرت الرجل، والسرح والرحل، وما يشدبه إسار، والفدا العوض الذي يخص به فكاك الإنسان وقيل الفدا والفداء واحد، والأقرب أن الفداء بالمد اسم لما يفدي به والفدى اسم للمفدى، كما يقال الحمى للمحمي وإن كان كل واحد منهما يوضع موضع الأخر، والحرام المنع الشديد من جهة الحكم، ورجل حرام يجوز أن يكون على وضع المصدر موضع الفاعل كأنه محرم على نفسه بالتزامه ما ألزم ما كان محللا له إما بدخوله الحرم أو بالإحرام، ويجور أن يكون في موضع المفعول، كأنه صار محروما أي ممنوعة من بعض ما كان مباحا له والشهر سمي محرما لذلك، واستحرمت الماء غيره، كأنها طلبت شيئا محرما في غيرها، وذلك كناية، والخزي ذل يستحي منه، ولتضمن المعنيين استعمل تارة في الذل نحو: عليه الخزي، وفي الاستحياء، نحو خزي،\n⟦1:252⟧\nوالرد والرجوع متقاربان، إلا أن الرد يقتضي قهرا، أما للمردود إذا استعمل في الحيوان والرجوع لا يقتضي ذلك، فإن قبل الردة عن الإسلام يتعاطاها صاحبها طوعا، قيل إذا اعتبرت الردة بصريح العقل والفطرة التي فطر الناس عليها، فهي قهر للعقل على ما ليس من مقتضاه، لأن الكفر هو الاعتقاد الظني، كما أن الإيمان هو الاعتقاد اليقيني، والعقل لا يسكن إلى الكفر، [ولا يطمئن إليه] إذهو مناف لمقتضاه، ولهذا قال تعالى: ﴿رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ﴾⟪15:2⟫ لأنهم إذا راجعوا عقولهم [أنكروه وتمنوا سواه]، وعلى ذلك قوله تعالى.\n﴿وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ﴾⟪22:31⟫\nومعنى الآية أن اليهود كان أوجب عليهم أن لا يسفكوا الدماء ولا يخرجوا أحدا من ديارهم ولم يوجب عليهم مفادات الأسرى، فأخلوا بالواجب والتزموا ما لم يكن يلزمهم، فأنكر الله تعالى عليهم ترك الفريضة ومراعاة النافلة وقوله: ﴿وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ﴾⟪2:85⟫ متعلق بما قبله وقد فصل بينهما بقوله: ﴿وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ﴾⟪2:85⟫ وقال بعضهم: إن الله تعالى نبه بهذه الآية مع المعنى الظاهر على لطيفة، وهي أن في قوله تعالى تقتلون أنفسكم تنبيه أنه تسعون في اكتساب العقاب الذي يجري مجرى قتل النفس، وبقوله: ﴿وَتُخۡرِجُونَ فَرِيقٗا مِّنكُم مِّن دِيَٰرِهِمۡ﴾⟪2:85⟫ أي تضيعون بعض قواكم ولا\n⟦1:253⟧\nتراعونها حق المرعاة، فإن من هذب قوته العالمة، ثم ضيع قوته العاملة.\nبالتقصير، [فقد ضيع نفسه] وكأنه أخرجها من محلها الذي جعله الله تعالي لها، وعلى ذلك ما إذا ضبط قوته الشهوية ولم يضبط قوته الغضبية، ونبه بقوله: ﴿وَإِن يَأۡتُوكُمۡ أُسَٰرَىٰ تُفَٰدُوهُمۡ﴾⟪2:85⟫ إنكم تتصدون لهدى غيركم مع تضييعكم أنفسكم كقوله: ﴿أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ﴾⟪2:44⟫، وعلى ذلك قيل: (كفى بالمرء تهزيا أن يعظ غيره وينسى نفسه)، وقوله: ﴿وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡۚ﴾⟪2:85⟫ فقد قيل: هو ضمير الحديث، وقيل: هو\nضمير المصدر الذي هو الإخراج، وقد أعيد ذكره تأكيده، فكأنه تكرير الخبر مراتين، ثم بين أن متعاطي ذلك له في الدنيا خزي ولهم في الآخرة عذاب عظيم، وعظم إبعادهم بتنبيههم أنه سبحانه بالمرصاد لا يغفل عن شي تعالى الله وتقدس ..."}, {"a": [86], "v": 1, "p": 253, "ev": 1, "ep": 255, "sid": 254, "t": "قوله - عز وجل -:\n﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۖ فَلَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنصَرُونَ﴾⟪2:86⟫\nالآية (86) سورة البقرة.\nالخفة والثقل يقالان على أضرب ، الأول: خفيف في المخسر لطلب العلو كالنار، وثقيل في المسخر لطلب السفل كالحجر، الثاني: يقال على سبيل التصادف كشيئين يترجح أحدهما على الآخر فيصح أن يوصف شي واحد بأنه خفيف وثقيل على اعتباره بشيئين، الثالث على اعتبار الزمان نحو أن يقال: هذا الفرس خفيف، وذاك ثقيل بمعنى أنه إذا اعتبر عددهما بزمان واحد كان أحدهما أكثر عددا من الآخر، والرابع: يقال فيما تستجليه النفس خفيف، وفيما تعافه ثقيل، فالخفيف على هذا مدح، والثقيل ذم الخامس على العكس من ذلك، وهو أن يقصد بالثقيل معنى الرزين، وبالخفيف\n⟦1:254⟧\nمعنى الطائش، والقصد باشتراء الحياة الدنيا في هذه الآية [وبالرضى في هذه الآية] وبايثارها في نحو قوله تعالى: ﴿فَأَمَّا مَن طَغَىٰ ۝ وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا﴾⟪79:37-38⟫ في نحو قوله: ﴿وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪10:7⟫ وبالإخلاد إليها في قوله تعالى ﴿وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ﴾⟪7:176⟫ وباتباع الهوى في نحو قوله، ﴿وَٱتَّبَعَ هَوَىٰهُۚ﴾ وبعبادة الشيطان في نحو قوله: ﴿لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ﴾⟪36:60⟫ وبإتباع الخطوات في نحو قوله: ﴿وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ﴾ وبنصرة الشيطان في قوله: ﴿أُوْلَٰٓئِكَ حِزۡبُ ٱلشَّيۡطَٰنِۚ﴾⟪58:19⟫ كل ذلك قصد واحد في أنه حث على تجنب المعاصي وأن اختلفت العبارات وتفاوتت الأنظار، وبين الله تعالى بالآية أن من فعل ذلك فهو معاقب لا يخفف عذابه، أما في الدنيا، فمعذب لشرهه على تتبع فضولات المال وجمعه، كما قال: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪9:55⟫، فلا يكون لطلبها غاية إذا انتهى إليها خفف عذابه، وأما في الآخرة فبدوام العذاب الأليم، وبين تعالى أنه لا يجد نصرة من جهة ماله في الدنيا، كما قال حكاية عن المحتضر: ﴿مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ﴾⟪69:28⟫ ولا في الآخرة، كما قال: ﴿مِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا﴾⟪45:10⟫ الآية، وقوله ﴿فَلَا يُخَفَّفُ عَنۡهُمُ﴾⟪2:86⟫ قيل: هو داخل في صلة الدين والصحيح أنه جواب لتضمن لفظه الذين معنى الشرط كما هو جواب في قوله: ﴿إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ﴾⟪85:10⟫.\n⟦1:255⟧"}];
